HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Valor Inventory Agent</title>\n<style>\n:root{--bg:#f4f5f7;--card:#fff;--side:#12151b;--sideink:#c8ccd4;--ink:#14171c;--mute:#6b7280;--line:#e5e7eb;--acc:#d62f2f;--ok:#15803d;--warn:#b45309;--blue:#1d4ed8;--soft:rgba(127,127,127,.08)}\n@media (prefers-color-scheme:dark){:root{--bg:#0d0f13;--card:#171a20;--side:#0a0c10;--ink:#eceef2;--mute:#9aa1ad;--line:#272c35;--acc:#ef5350;--ok:#4ade80;--warn:#fbbf24;--blue:#60a5fa}}\n*{box-sizing:border-box}html,body{height:100%}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 "Segoe UI",system-ui,sans-serif}\n#app{display:grid;grid-template-columns:210px 1fr;height:100vh}\naside{background:var(--side);color:var(--sideink);overflow:auto;padding:14px 10px}\naside .logo{font-weight:700;color:#fff;font-size:15px;padding:4px 10px 14px}aside .logo span{color:var(--acc)}\naside h6{margin:14px 10px 4px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#7b8190;font-weight:600}\naside button{display:flex;width:100%;align-items:center;justify-content:space-between;text-align:left;background:none;border:0;color:inherit;padding:7px 10px;border-radius:7px;cursor:pointer;font:inherit}\naside button:hover{background:rgba(255,255,255,.07)}aside button.on{background:var(--acc);color:#fff}\n.badge{background:var(--acc);color:#fff;border-radius:9px;padding:0 6px;font-size:11px}aside button.on .badge{background:#fff;color:var(--acc)}\n.mainwrap{display:flex;flex-direction:column;min-width:0;height:100vh}\nheader{display:flex;align-items:center;gap:10px;padding:10px 22px;background:var(--card);border-bottom:1px solid var(--line);flex-wrap:wrap}\nheader h1{font-size:18px;margin:0;flex:1;min-width:140px}\nmain{flex:1;overflow:auto;padding:18px 22px 60px}\n#banner{display:none;padding:9px 22px;background:var(--ok);color:#fff;gap:12px;align-items:center}#banner.on{display:flex}#banner button{background:#fff;color:#111;border:0;border-radius:6px;padding:4px 12px;cursor:pointer;font:inherit}\n.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:16px}\n.tile{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px}\n.tile b{display:block;font-size:21px;margin-top:2px}.tile span{color:var(--mute);font-size:12px}\n.panels{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:12px;margin-bottom:12px}\n.panel{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px;overflow:auto}\n.panel h3{margin:0 0 8px;font-size:13px;color:var(--mute);font-weight:600;text-transform:uppercase;letter-spacing:.05em}\n.card{background:var(--card);border:1px solid var(--line);border-radius:10px;overflow:auto}\ntable{width:100%;border-collapse:collapse}th,td{padding:8px 10px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}\ntr:last-child td{border-bottom:0}th{font-size:12px;color:var(--mute);font-weight:600;position:sticky;top:0;background:var(--card)}td.wrap{white-space:normal;min-width:200px}td.num,th.num{text-align:right}\nbutton.b,input,select,textarea{font:inherit;padding:6px 10px;border-radius:7px;border:1px solid var(--line);background:var(--card);color:var(--ink)}\nbutton.b{cursor:pointer}button.b:hover{border-color:var(--mute)}button.p{background:var(--acc);border-color:var(--acc);color:#fff}button.b:disabled{opacity:.5;cursor:default}\ninput:focus,select:focus,textarea:focus{outline:2px solid var(--blue);outline-offset:-1px}\n.bar{display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center}\n.pill{padding:1px 9px;border-radius:9px;font-size:12px;border:1px solid var(--line);display:inline-block}\n.confirmed,.in-stock{color:var(--blue)}.shipped,.listed-for-sale,.partially-sold{color:var(--warn)}.delivered,.sold{color:var(--ok)}.cancelled{color:var(--mute);text-decoration:line-through}\ndialog.wide{max-width:780px}dialog{max-height:92vh;overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card);color:var(--ink);max-width:480px;width:94%;padding:18px}\ndialog::backdrop{background:rgba(0,0,0,.45)}\ndialog label{display:block;margin:8px 0 2px;font-size:12px;color:var(--mute)}dialog input,dialog select,dialog textarea{width:100%}\n.log{font:12px ui-monospace,Consolas,monospace;color:var(--mute);white-space:pre-wrap;margin-top:8px;max-height:140px;overflow:auto}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}fieldset{border:1px solid var(--line);border-radius:8px;margin:10px 0;padding:6px 10px 10px}legend{font-size:12px;color:var(--mute)}\ndiv.mrow{display:flex;flex-direction:column;padding:4px 6px;border-radius:6px}div.mrow input[data-v],div.mrow select[data-v]{opacity:.45}div.mrow.on{background:rgba(214,47,47,.08)}div.mrow.on input[data-v],div.mrow.on select[data-v]{opacity:1}\nlabel.cbl{display:inline-flex;align-items:center;gap:6px;margin:6px 14px 6px 0;color:var(--ink);font-size:13px}dialog label.cbl input{width:auto}\n.ibrow{padding:9px 12px;border-bottom:1px solid var(--line);cursor:pointer}.ibrow:hover{background:var(--soft)}.ibrow.on{background:rgba(214,47,47,.1)}\n.muted{color:var(--mute)}.neg{color:var(--acc)}.pos{color:var(--ok)}\n.prog{background:var(--line);border-radius:6px;height:10px;overflow:hidden}.prog i{display:block;height:10px;background:var(--acc)}\n.big{font-size:34px;font-weight:700}\n#toast{display:none;position:fixed;inset:auto 20px 20px auto;margin:0;border:0;background:#1f2937;color:#fff;padding:11px 16px;border-radius:9px;max-width:420px;box-shadow:0 8px 24px rgba(0,0,0,.35);white-space:pre-wrap}\n#toast:popover-open{display:block}#toast.bad{background:#b91c1c}\n.scanbox input{font-size:22px;padding:12px 14px;width:100%}\n.seg button{border-radius:0}.seg button:first-child{border-radius:7px 0 0 7px}.seg button:last-child{border-radius:0 7px 7px 0}.seg button.on{background:var(--acc);color:#fff;border-color:var(--acc)}\n/* privacy blur */\n.sens{transition:filter .15s}\nbody.priv-on.pv-addr .s-addr,body.priv-on.pv-card .s-card,body.priv-on.pv-contact .s-contact,body.priv-on.pv-secret .s-secret{filter:blur(6px);cursor:pointer;user-select:none}\nbody.priv-on .sens.show,body.priv-on input.sens:focus{filter:none!important;user-select:text}\n.addr{line-height:1.35;min-width:170px}.addr small{color:var(--mute)}\n.privbar{display:flex;gap:6px 14px;flex-wrap:wrap;align-items:center;padding:8px 12px;margin-bottom:10px;border:1px solid var(--line);border-radius:10px;background:var(--card)}\n.privbar.on{border-color:var(--blue)}\n@media(max-width:900px){#app{grid-template-columns:1fr}aside{display:flex;flex-wrap:wrap;gap:4px;padding:8px}aside h6{display:none}aside button{width:auto}.mainwrap{height:auto}.grid2{grid-template-columns:1fr}.ibgrid{grid-template-columns:1fr!important}}\n</style></head><body>\n<div id="app"><aside><div class="logo">Valor <span>Inventory</span> Agent</div><div id="nav"></div></aside>\n<div class="mainwrap"><div id="banner"></div>\n<header><h1 id="title"></h1><span id="syncmsg" class="muted"></span>\n<button class="b p" id="syncbtn">Sync iCloud email</button><button class="b" id="rescanbtn" title="Re-read every email in the look-back window">Re-scan all</button><button class="b" id="privbtn" onclick="PRIV.on=!PRIV.on;savePriv();render()" title="Blur addresses, cards, emails and passwords on screen">Blur: off</button><button class="b" onclick="api(\'open_exports\',{})">Exports folder</button></header>\n<main><div id="view"></div></main></div></div>\n<dialog id="dlg"><form method="dialog" id="form"></form></dialog>\n<div id="toast" popover="manual"></div>\n<script>\n\nconst $=s=>document.querySelector(s);\nconst money=n=>n==null||n===\'\'?\'\':(n<0?\'-\':\'\')+\'$\'+Math.abs(+n||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});\nconst pct=n=>n==null?\'\':(n*100).toFixed(1)+\'%\';\nconst esc=s=>String(s??\'\').replace(/[&<>"]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\'}[c]));\nconst api=(p,b)=>fetch(\'/api/\'+p,b===undefined?{}:{method:\'POST\',body:JSON.stringify(b)}).then(r=>r.json()).catch(e=>({error:\'Could not reach the app: \'+e.message}));\nconst q=s=>JSON.stringify(s).replace(/"/g,\'&quot;\');\nfunction toast(msg,bad){const t=$(\'#toast\');t.textContent=msg;t.className=bad?\'bad\':\'\';try{t.hidePopover()}catch(e){}\n  try{t.showPopover()}catch(e){t.style.display=\'block\'}clearTimeout(toast.t);toast.t=setTimeout(()=>{try{t.hidePopover()}catch(e){}t.style.display=\'\'},bad?6000:3500)}\nconst NAV=[[\'Overview\',[[\'dashboard\',\'Dashboard\']]],\n [\'Business\',[[\'inventory\',\'Inventory\'],[\'sales\',\'Sales\'],[\'receipts\',\'Receipts\'],[\'scan\',\'Scan Station\'],[\'tax\',\'Tax Summary\']]],\n [\'Orders\',[[\'orders\',\'Orders\'],[\'inbox\',\'Inbox\'],[\'limits\',\'Purchase Limits\'],[\'review\',\'Review\']]],\n [\'Valor AIO\',[[\'accounts\',\'Accounts\'],[\'profiles\',\'Profiles\']]],\n [\'App\',[[\'settings\',\'Settings\'],[\'updates\',\'Updates\'],[\'reference\',\'Visual Reference\']]]];\nconst TITLES={dashboard:\'Dashboard\',inventory:\'Inventory\',sales:\'Sales\',receipts:\'Receipts\',scan:\'Scan Station\',tax:\'Tax Summary\',orders:\'Orders\',inbox:\'Inbox\',limits:\'Purchase Limits\',review:\'Review queue\',accounts:\'Valor Accounts\',profiles:\'Valor Profiles\',settings:\'Settings\',updates:\'Updates\',reference:\'Visual Reference\'};\nconst SITES=[\'Pokemon Center\',\'Target\',\'Walmart\',\'Best Buy\',\'GameStop\',\'Costco\',"Sam\'s Club"];\nlet tab=\'dashboard\',data={},filter=\'\',openSites={},L={},TS={settings:{},fees:[],currencies:[]},DASH={},TAX=null,SCANS=[],SC={mode:\'receive\',sold_by:\'\',msg:\'\',bad:false};\nlet IF={status:\'\',category:\'\'};\n\nasync function load(){\n  const g=p=>api(p);\n  const [inv,sal,rec,dash,ord,rev,acc,prof,lim,lists,ts,scans]=await Promise.all([\'items\',\'tsales\',\'receipts\',\'dashboard\',\'orders\',\'review\',\'vaccounts\',\'vprofiles\',\'limits\',\'lists\',\'tsettings\',\'scans\'].map(g));\n  data={inv:inv.error?[]:inv,sal:sal.error?[]:sal,rec:rec.error?[]:rec,ord:ord.error?[]:ord,rev:rev.error?[]:rev,acc:acc.error?[]:acc,prof:prof.error?[]:prof,lim:lim.error?[]:lim};\n  DASH=dash;L=lists;TS=ts;SCANS=scans.error?[]:scans;\n  [inv,sal,dash,lists].forEach(r=>{if(r&&r.error)toast(r.error,true)});\n  render();\n}\nfunction nav(){\n  $(\'#nav\').innerHTML=NAV.map(([g,ts])=>`<h6>${g}</h6>`+ts.map(([k,l])=>`<button class="${k==tab?\'on\':\'\'}" onclick="go(\'${k}\')">${l}${k==\'review\'&&data.rev&&data.rev.length?`<span class="badge">${data.rev.length}</span>`:\'\'}${k==\'updates\'&&UPD.info&&UPD.info.ok&&UPD.info.update?\'<span class="badge">new</span>\':\'\'}</button>`).join(\'\')).join(\'\');\n  $(\'#title\').textContent=TITLES[tab]||\'\';\n}\nfunction go(t){tab=t;filter=\'\';if(t==\'tax\')TAX=null;render();$(\'main\').scrollTop=0}\nfunction render(){\n  nav();\n  const v={dashboard:vDash,inventory:vInv,sales:vSal,receipts:vRecs,scan:vScan,tax:vTax,orders:vOrd,inbox:vInbox,limits:vLim,review:vRev,accounts:vAcc,profiles:vProf,settings:vSet,updates:vUpd,reference:vRef}[tab];\n  const keep=document.activeElement&&document.activeElement.id===\'flt\'?document.activeElement.selectionStart:null;\n  $(\'#view\').innerHTML=v();\n  if(keep!==null){const e=$(\'#flt\');if(e){e.focus();e.setSelectionRange(keep,keep)}}\n  if(tab==\'scan\'){const e=$(\'#scansku\');if(e&&!$(\'#dlg\').open)e.focus()}\n  if(tab==\'tax\'&&!TAX)taxLoad();\n}\nconst f=()=>`<input id="flt" placeholder="Filter…" value="${esc(filter)}" oninput="filter=this.value;render()">`;\nconst dl=(id,arr)=>`<datalist id="${id}">${(arr||[]).map(s=>`<option value="${esc(s)}">`).join(\'\')}</datalist>`;\nconst pill=s=>`<span class="pill ${String(s).toLowerCase().replace(/\\s+/g,\'-\')}">${esc(s)}</span>`;\nconst tile=(l,v,cls=\'\')=>`<div class="tile"><span>${l}</span><b class="${cls}">${v}</b></div>`;\nconst sgn=n=>n<0?\'neg\':n>0?\'pos\':\'\';\nconst tbl=(head,rows,empty)=>`<div class="card"><table><tr>${head}</tr>${rows||`<tr><td class="muted" colspan="20">${empty}</td></tr>`}</table></div>`;\nconst mini=(head,rows,empty)=>`<table><tr>${head}</tr>${rows||`<tr><td class="muted" colspan="9">${empty}</td></tr>`}</table>`;\n\n/* ---------------------------------------------------------- dashboard */\nfunction chart(months){\n  const W=560,H=190,pl=8,pb=26,pt=10,h=H-pb-pt,bw=(W-pl*2)/months.length;\n  const vals=months.flatMap(m=>[m.revenue,m.profit,0]);const mx=Math.max(...vals,1),mn=Math.min(...vals,0);\n  const y=v=>pt+(mx-v)/(mx-mn)*h;\n  return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Revenue and profit by month"><line x1="0" x2="${W}" y1="${y(0)}" y2="${y(0)}" stroke="currentColor" opacity=".25"/>`+\n  months.map((m,i)=>{const x=pl+i*bw+bw*.12,w=bw*.34;\n    const bar=(v,c,dx)=>{const y0=y(0),y1=y(v);return `<rect x="${x+dx}" y="${Math.min(y0,y1)}" width="${w}" height="${Math.max(1,Math.abs(y0-y1))}" rx="2" fill="${c}"><title>${m.label}: ${money(v)}</title></rect>`};\n    return bar(m.revenue,\'#9aa1ad\',0)+bar(m.profit,m.profit<0?\'#ef5350\':\'#15803d\',w+3)+`<text x="${pl+i*bw+bw/2}" y="${H-8}" text-anchor="middle" font-size="11" fill="currentColor" opacity=".7">${m.label.slice(0,3)}</text>`}).join(\'\')+`</svg>\n  <div class="muted" style="font-size:12px"><span style="color:#9aa1ad">■</span> Revenue &nbsp; <span style="color:#15803d">■</span> Profit</div>`;\n}\nfunction vDash(){\n  const d=DASH;if(!d||d.error||!d.months)return \'<div class="muted">Loading…</div>\';\n  const t=d.target;\n  return `<div class="tiles">${tile(\'In stock\',d.in_stock+\' units\')}${tile(\'Cost on hand\',money(d.cost_on_hand))}${tile(\'Market value\',money(d.market_value))}${tile(\'Units sold\',d.sold)}${tile(\'Revenue\',money(d.revenue))}${tile(\'Fees\',money(d.fees))}${tile(\'Expenses (receipts)\',money(d.expenses))}${tile(\'Net profit\',money(d.net_profit),sgn(d.net_profit))}${tile(\'ROI\',d.roi==null?\'—\':pct(d.roi))}</div>\n  ${d.aging_count?`<div class="panel" style="border-color:var(--warn);margin-bottom:12px"><b style="color:var(--warn)">${d.aging_count} item(s) have been in stock ${d.aging_days}+ days.</b> Consider lowering prices — see the list below.</div>`:\'\'}\n  <div class="panels"><div class="panel"><h3>Last 6 months</h3>${chart(d.months)}</div>\n  <div class="panel"><h3>Monthly profit target</h3>${t.target?`<div class="big ${sgn(t.so_far)}">${money(t.so_far)} <span class="muted" style="font-size:15px">of ${money(t.target)}</span></div><div class="prog"><i style="width:${Math.min(100,Math.max(0,t.so_far/t.target*100))}%"></i></div><p class="muted">${t.remaining?`${money(t.remaining)} to go${t.more_sales?` — about ${t.more_sales} more sales at your ${money(t.avg_profit)} average profit`:\'\'}.`:\'Target reached this month 🎉\'}</p>`:\'<p class="muted">Set a monthly profit target in Settings to track it here.</p>\'}\n  <h3 style="margin-top:14px">Find a SKU</h3><div class="bar"><input id="skuq" placeholder="PK-0001" onkeydown="if(event.key==\'Enter\')skuFind()"><button class="b" onclick="skuFind()">Look up</button></div><div id="skures"></div></div></div>\n  <div class="panels"><div class="panel"><h3>By category</h3>${mini(\'<th>Category</th><th class="num">Sold</th><th class="num">Revenue</th><th class="num">Profit</th>\',d.by_category.map(c=>`<tr><td>${esc(c.category)}</td><td class="num">${c.units}</td><td class="num">${money(c.revenue)}</td><td class="num ${sgn(c.profit)}">${money(c.profit)}</td></tr>`).join(\'\'),\'\')}</div>\n  <div class="panel"><h3>By team member</h3>${mini(\'<th>Name</th><th class="num">Sales</th><th class="num">Revenue</th><th class="num">Profit</th>\',d.by_member.map(c=>`<tr><td>${esc(c.name)}</td><td class="num">${c.sales}</td><td class="num">${money(c.revenue)}</td><td class="num ${sgn(c.profit)}">${money(c.profit)}</td></tr>`).join(\'\'),\'\')}</div></div>\n  <div class="panels"><div class="panel"><h3>Top 5 sales by profit</h3>${mini(\'<th>Item</th><th class="num">Profit</th><th class="num">ROI</th>\',d.top_sales.map(s=>`<tr><td class="wrap">${esc(s.item)}<div class="muted">${esc(s.sku)}</div></td><td class="num pos">${money(s.profit)}</td><td class="num">${pct(s.roi)}</td></tr>`).join(\'\'),\'No sales yet.\')}</div>\n  <div class="panel"><h3>Restock suggestions (30 days)</h3>${mini(\'<th>Category</th><th class="num">Sold</th><th class="num">In stock</th><th>Suggestion</th>\',d.reorder.map(r=>`<tr><td>${esc(r.category)}</td><td class="num">${r.sold_30d}</td><td class="num">${r.in_stock}</td><td class="${r.suggestion==\'Restock soon\'?\'neg\':r.suggestion==\'OK\'?\'muted\':\'pos\'}">${r.suggestion}</td></tr>`).join(\'\'),\'\')}</div></div>\n  <div class="panels"><div class="panel"><h3>Oldest stock — price-drop ideas</h3>${mini(\'<th>Item</th><th class="num">Days</th><th class="num">Listed</th><th class="num">Suggested</th>\',d.price_drops.map(p=>`<tr><td class="wrap">${esc(p.item)}<div class="muted">${esc(p.sku)}</div></td><td class="num">${p.days}</td><td class="num">${p.listed?money(p.listed):\'—\'}</td><td class="num">${p.suggested?money(p.suggested):\'—\'}</td></tr>`).join(\'\'),\'Nothing in stock.\')}</div>\n  <div class="panel"><h3>Recent sales</h3>${mini(\'<th>Date</th><th>Item</th><th class="num">Price</th><th class="num">Profit</th>\',d.recent_sales.map(s=>`<tr><td>${esc(s.date)}</td><td class="wrap">${esc(s.item)}</td><td class="num">${money(s.price)}</td><td class="num ${sgn(s.profit)}">${money(s.profit)}</td></tr>`).join(\'\'),\'No sales yet.\')}\n  <p class="muted" style="margin:10px 0 0">Repeat buyers: <b>${d.repeat_buyers.count}</b> (${money(d.repeat_buyers.revenue)} revenue)</p></div></div>`;\n}\nasync function skuFind(){\n  const v=($(\'#skuq\').value||\'\').trim();if(!v)return;const r=await api(\'sku?sku=\'+encodeURIComponent(v));const it=r.item;\n  $(\'#skures\').innerHTML=it?`<div class="panel" style="margin-top:8px"><b>${esc(it.name)}</b> ${pill(it.status)}<br><span class="muted">${esc(it.sku)} · ${esc(it.category)}</span><br>Qty ${it.qty} · sold ${it.qty_sold} · left <b>${it.qty_remaining}</b><br>Unit cost ${money(it.purchase_price)} · listed ${it.listed_price?money(it.listed_price):\'—\'}${it.profit!=null?` · profit <span class="${sgn(it.profit)}">${money(it.profit)}</span>`:\'\'}<br><button class="b" style="margin-top:6px" onclick="invDlg(${it.id})">Open</button></div>`:`<p class="neg">No item with SKU ${esc(v.toUpperCase())}.</p>`;\n}\n\n/* ---------------------------------------------------------- inventory */\nfunction photoLink(r){return r.photo?`<a href="#" onclick="openUrl(${q(r.photo)});return false" title="Find photos online">🔍</a>`:\'\'}\nasync function openUrl(u){const r=await api(\'open_url\',{url:u});if(r.error)toast(r.error,true)}\nfunction vInv(){\n  const t=filter.toLowerCase();\n  const rows=data.inv.filter(r=>(!t||(r.name+r.sku+r.pokemon_set+r.card_no+r.location).toLowerCase().includes(t))&&(!IF.status||r.status==IF.status)&&(!IF.category||r.category==IF.category));\n  return `<div class="bar">${f()}<select onchange="IF.status=this.value;render()"><option value="">All statuses</option>${[\'In Stock\',\'Listed for Sale\',\'Partially Sold\',\'Sold\'].map(s=>`<option ${IF.status==s?\'selected\':\'\'}>${s}</option>`).join(\'\')}</select>\n  <select onchange="IF.category=this.value;render()"><option value="">All categories</option>${(L.categories||[]).map(s=>`<option ${IF.category==s?\'selected\':\'\'}>${esc(s)}</option>`).join(\'\')}</select>\n  <button class="b p" onclick="invDlg()">+ Add item</button><button class="b" onclick="csvImport(\'inventory\')">Import CSV</button><button class="b" onclick="csvExport(\'inventory\')">Export CSV</button><span class="muted">${rows.length} of ${data.inv.length}</span></div>\n  ${tbl(\'<th>SKU</th><th>Item</th><th>Category</th><th>Set / Card #</th><th>Cond. / Grade</th><th class="num">Qty</th><th class="num">Sold</th><th class="num">Left</th><th>Status</th><th class="num">Unit cost</th><th class="num">Listed</th><th class="num">Profit</th><th class="num">ROI</th><th class="num">Days</th><th></th>\',\n  rows.map(r=>`<tr><td>${esc(r.sku)} ${photoLink(r)}</td><td class="wrap">${esc(r.name)}<div class="muted">${esc(r.location)}</div></td><td>${esc(r.category)}</td><td>${esc(r.pokemon_set)} ${esc(r.card_no)}</td><td>${esc(r.condition)} ${esc(r.grading)}</td><td class="num">${r.qty}</td><td class="num">${r.qty_sold}</td><td class="num"><b>${r.qty_remaining}</b></td><td>${pill(r.status)}</td><td class="num">${money(r.purchase_price)}</td><td class="num">${r.listed_price?money(r.listed_price):\'\'}</td><td class="num ${sgn(r.profit)}">${money(r.profit)}</td><td class="num">${pct(r.roi)}</td><td class="num">${r.days_held??\'\'}</td><td><button class="b" onclick="invDlg(${r.id})">Edit</button> <button class="b" onclick="saleDlg(null,${r.id})" ${r.qty_remaining?\'\':\'disabled\'}>Sell</button></td></tr>`).join(\'\'),\'No items match. Click “+ Add item”, or sync your email to add delivered orders automatically.\')}\n  ${dl(\'l_sets\',L.pokemon_sets)}${dl(\'l_cond\',L.conditions)}${dl(\'l_grade\',L.grading)}${dl(\'l_src\',L.purchase_sources)}${dl(\'l_plat\',L.platforms)}`;\n}\nfunction invDlg(id,pre){\n  const r=data.inv.find(x=>x.id==id)||pre||{};\n  const sel=(n,l,opts,v)=>`<div><label>${l}</label><select name="${n}">${opts.map(o=>`<option ${o==v?\'selected\':\'\'}>${esc(o)}</option>`).join(\'\')}</select></div>`;\n  const i=(n,l,v,t=\'text\',x=\'\',list=\'\')=>`<div><label>${l}</label><input name="${n}" type="${t}" value="${esc(v??\'\')}" ${x} ${list?`list="${list}"`:\'\'}></div>`;\n  dlg(`<div class="grid2">${i(\'name\',\'Item name\',r.name,\'text\',\'required\')}${i(\'sku\',\'SKU (blank = auto)\',r.sku,\'text\',\'placeholder="PK-0001"\')}\n  ${sel(\'category\',\'Category\',L.categories||[],r.category||\'Pokemon Card\')}${i(\'pokemon_set\',\'Pokémon set\',r.pokemon_set,\'text\',\'\',\'l_sets\')}\n  ${i(\'card_no\',\'Card #\',r.card_no)}${i(\'condition\',\'Condition\',r.condition,\'text\',\'\',\'l_cond\')}${i(\'grading\',\'Grading\',r.grading,\'text\',\'\',\'l_grade\')}${i(\'qty\',\'Quantity purchased\',r.qty??1,\'number\',\'min=1\')}\n  ${sel(\'added_by\',\'Added by\',[\'\',...(L.team||[])],r.added_by||\'\')}${i(\'purchase_date\',\'Purchase date\',r.purchase_date||new Date().toISOString().slice(0,10),\'date\')}\n  ${i(\'purchase_price\',\'Purchase price (each)\',r.purchase_price??0,\'number\',\'step=0.01 min=0\')}${sel(\'currency\',\'Currency\',L.currencies||[\'USD\'],r.currency||\'USD\')}\n  ${i(\'purchase_source\',\'Purchased from\',r.purchase_source,\'text\',\'\',\'l_src\')}${i(\'listing_platform\',\'Listed on\',r.listing_platform,\'text\',\'\',\'l_plat\')}\n  ${i(\'listed_price\',\'Listed price (each)\',r.listed_price||\'\',\'number\',\'step=0.01 min=0\')}${i(\'market_price\',\'Market price (each)\',r.market_price||\'\',\'number\',\'step=0.01 min=0\')}\n  ${i(\'location\',\'Location / bin\',r.location)}${i(\'notes\',\'Notes\',r.notes)}</div>`\n  +(r.id?`<p><button type="button" class="b" onclick="delInv(${r.id})">Delete item</button></p>`:\'\'),\n  fd=>api(\'items/save\',{...fd,id:r.id||null}),\'wide\');\n}\nasync function delInv(id){if(confirm(\'Delete this item? Items with sales must have those sales deleted first.\')){const r=await api(\'items/delete\',{id});if(r.error)return toast(r.error,true);$(\'#dlg\').close();load()}}\n\n/* ---------------------------------------------------------- sales */\nfunction vSal(){\n  const t=filter.toLowerCase();\n  const rows=data.sal.filter(s=>!t||(s.item_name+s.sku+s.buyer+s.platform+s.sale_id).toLowerCase().includes(t));\n  const tot=rows.reduce((a,s)=>({r:a.r+s.sale_price,p:a.p+(s.profit||0),f:a.f+(s.total_fees||0)}),{r:0,p:0,f:0});\n  return `<div class="bar">${f()}<button class="b p" onclick="saleDlg()">+ Log sale</button><button class="b" onclick="csvImport(\'sales\')">Import CSV</button><button class="b" onclick="csvExport(\'sales\')">Export CSV</button><span class="muted">${rows.length} sales · revenue ${money(tot.r)} · fees ${money(tot.f)} · profit <b class="${sgn(tot.p)}">${money(tot.p)}</b></span></div>\n  ${tbl(\'<th>Sale</th><th>Date</th><th>Item</th><th>Platform</th><th>Buyer</th><th>By</th><th class="num">Qty</th><th class="num">Price</th><th class="num">Fees</th><th class="num">Ship cost</th><th class="num">Net</th><th class="num">Cost</th><th class="num">Profit</th><th class="num">ROI</th><th></th>\',\n  rows.map(s=>`<tr><td>${esc(s.sale_id)}</td><td>${esc(s.sale_date)}</td><td class="wrap">${esc(s.item_name)}<div class="muted">${esc(s.sku)}</div></td><td>${esc(s.platform)}</td><td>${esc(s.buyer)}${s.buyer_count>1?` <span class="pill">×${s.buyer_count}</span>`:\'\'}</td><td>${esc(s.sold_by)}</td><td class="num">${s.qty}</td><td class="num">${money(s.sale_price)}</td><td class="num">${money(s.total_fees)}</td><td class="num">${money(s.ship_cost)}</td><td class="num">${money(s.net)}</td><td class="num">${money(s.cost_basis)}</td><td class="num ${sgn(s.profit)}">${money(s.profit)}</td><td class="num">${pct(s.roi)}</td><td><button class="b" onclick="saleDlg(${s.id})">Edit</button></td></tr>`).join(\'\'),\'No sales yet. Use “Sell” on an inventory row, “+ Log sale”, or the Scan Station.\')}`;\n}\nfunction feeCalc(){\n  const g=n=>+(document.querySelector(`#form [name=${n}]`)||{}).value||0;\n  const plat=(TS.fees||[]).find(x=>x.platform==(document.querySelector(\'#form [name=platform]\')||{}).value);\n  const it=data.inv.find(x=>x.sku==(document.querySelector(\'#form [name=sku]\')||{}).value);\n  const gross=g(\'sale_price\')+g(\'ship_charged\');const fee=plat?gross*plat.fee_pct+plat.fixed:0;\n  const tf=fee+g(\'other_fees\'),net=g(\'sale_price\')+g(\'ship_charged\')-tf-g(\'ship_cost\');\n  const basis=it?g(\'qty\')*it.purchase_price*(it.fx||1):null;\n  const el=$(\'#feeprev\');if(el)el.innerHTML=`Platform fee <b>${money(fee)}</b> · total fees <b>${money(tf)}</b> · net <b>${money(net)}</b>${basis!=null?` · profit <b class="${sgn(net-basis)}">${money(net-basis)}</b>`:\'\'}`;\n}\nfunction saleDlg(id,sku){\n  const s=id?data.sal.find(x=>x.id==id):null;const cur=s?s.sku:(typeof sku==\'number\'?(data.inv.find(x=>x.id==sku)||{}).sku:sku)||\'\';\n  const avail=data.inv.filter(x=>x.qty_remaining>0||x.sku==cur);\n  if(!avail.length)return toast(\'Add inventory first — there is nothing left to sell.\',true);\n  const v=s||{qty:1,sale_date:new Date().toISOString().slice(0,10),sold_by:\'\',platform:\'\'};\n  const it0=data.inv.find(x=>x.sku==cur);if(!s&&it0){v.platform=it0.listing_platform;v.sale_price=it0.listed_price||\'\'}\n  const i=(n,l,val,t=\'text\',x=\'\')=>`<div><label>${l}</label><input name="${n}" type="${t}" value="${esc(val??\'\')}" ${x} oninput="feeCalc()"></div>`;\n  dlg(`<div class="grid2"><div style="grid-column:1/-1"><label>Item</label><select name="sku" onchange="feeCalc()">${avail.map(x=>`<option value="${esc(x.sku)}" ${x.sku==cur?\'selected\':\'\'}>${esc(x.sku)} — ${esc(x.name)} (${x.qty_remaining} left)</option>`).join(\'\')}</select></div>\n  ${i(\'qty\',\'Units sold\',v.qty,\'number\',\'min=1\')}${i(\'sale_price\',\'Sale price (total for these units)\',v.sale_price,\'number\',\'step=0.01 min=0 required\')}\n  ${i(\'ship_charged\',\'Shipping charged to buyer\',v.ship_charged||\'\',\'number\',\'step=0.01 min=0\')}${i(\'ship_cost\',\'Your shipping cost\',v.ship_cost||\'\',\'number\',\'step=0.01 min=0\')}\n  <div><label>Platform</label><select name="platform" onchange="feeCalc()"><option value=""></option>${(TS.fees||[]).map(x=>`<option ${x.platform==v.platform?\'selected\':\'\'}>${esc(x.platform)}</option>`).join(\'\')}</select></div>\n  ${i(\'other_fees\',\'Other fees\',v.other_fees||\'\',\'number\',\'step=0.01 min=0\')}${i(\'buyer\',\'Buyer\',v.buyer)}\n  <div><label>Sold by</label><select name="sold_by"><option value=""></option>${(L.team||[]).map(x=>`<option ${x==v.sold_by?\'selected\':\'\'}>${esc(x)}</option>`).join(\'\')}</select></div>\n  ${i(\'sale_date\',\'Sale date\',v.sale_date,\'date\')}${i(\'notes\',\'Notes\',v.notes)}</div><p id="feeprev" class="muted"></p>`\n  +(s?`<p><button type="button" class="b" onclick="delSale(${s.id})">Delete sale</button></p>`:\'\'),\n  fd=>api(\'tsales/save\',{...fd,id:s?s.id:null}).then(r=>{if(r&&r.alert)toast(r.alert);return r}),\'wide\');\n  feeCalc();\n}\nasync function delSale(id){if(confirm(\'Delete this sale? The units go back to stock.\')){const r=await api(\'tsales/delete\',{id});if(r.error)return toast(r.error,true);$(\'#dlg\').close();load()}}\n\n/* ---------------------------------------------------------- receipts */\nfunction vRecs(){\n  const t=filter.toLowerCase();const rows=data.rec.filter(r=>!t||(r.vendor+r.category+r.description+r.sku).toLowerCase().includes(t));\n  const tot=rows.reduce((a,r)=>a+r.amount,0);\n  return `<div class="bar">${f()}<button class="b p" onclick="recDlg()">+ Add receipt</button><button class="b" onclick="csvImport(\'receipts\')">Import CSV</button><button class="b" onclick="csvExport(\'receipts\')">Export CSV</button><span class="muted">${rows.length} receipts · ${money(tot)}</span></div>\n  ${tbl(\'<th>Date</th><th>Vendor</th><th>Category</th><th>Description</th><th>SKU</th><th class="num">Amount</th><th>Method</th><th></th>\',rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.vendor)}</td><td>${esc(r.category)}</td><td class="wrap">${esc(r.description)}</td><td>${esc(r.sku)}</td><td class="num">${money(r.amount)}</td><td>${esc(r.method)}</td><td><button class="b" onclick="recDlg(${r.id})">Edit</button></td></tr>`).join(\'\'),\'No receipts yet. Record business expenses (shipping supplies, postage, fees) here.\')}`;\n}\nfunction recDlg(id){\n  const r=data.rec.find(x=>x.id==id)||{date:new Date().toISOString().slice(0,10)};\n  const i=(n,l,v,t=\'text\',x=\'\',list=\'\')=>`<div><label>${l}</label><input name="${n}" type="${t}" value="${esc(v??\'\')}" ${x} ${list?`list="${list}"`:\'\'}></div>`;\n  dlg(`<div class="grid2">${i(\'date\',\'Date\',r.date,\'date\')}${i(\'amount\',\'Amount\',r.amount,\'number\',\'step=0.01 required\')}${i(\'vendor\',\'Vendor\',r.vendor)}${i(\'category\',\'Category\',r.category,\'text\',\'\',\'l_rc\')}${i(\'description\',\'Description\',r.description)}${i(\'sku\',\'SKU (optional)\',r.sku,\'text\',\'\',\'l_skus\')}${i(\'method\',\'Payment method\',r.method,\'text\',\'\',\'l_pm\')}${i(\'ref\',\'Reference / order #\',r.ref)}</div>${i(\'notes\',\'Notes\',r.notes)}${dl(\'l_rc\',L.receipt_categories)}${dl(\'l_pm\',L.payment_methods)}${dl(\'l_skus\',L.skus)}`\n   +(r.id?`<p><button type="button" class="b" onclick="delRec(${r.id})">Delete receipt</button></p>`:\'\'),fd=>api(\'receipts/save\',{...fd,id:r.id||null}));\n}\nasync function delRec(id){if(confirm(\'Delete this receipt?\')){await api(\'receipts/delete\',{id});$(\'#dlg\').close();load()}}\n\n/* ---------------------------------------------------------- csv */\nasync function csvExport(name){\n  const r=await api(\'export\',{name});if(r.error)return toast(r.error,true);\n  if(!window.pywebview){const a=document.createElement(\'a\');a.href=URL.createObjectURL(new Blob([r.csv],{type:\'text/csv\'}));a.download=r.filename;document.body.appendChild(a);a.click();a.remove()}\n  toast(\'Saved to \'+r.saved_to);\n}\nfunction csvImport(name){\n  dlg(`<p class="muted">Choose a CSV with the same column names as the export. Rows that fail validation are skipped and listed.</p><input type="file" accept=".csv,text/csv" id="csvfile" required>`,\n  async()=>{const f=$(\'#csvfile\').files[0];if(!f)return{error:\'Choose a file\'};const r=await api(\'import\',{name,csv:await f.text()});if(r.error)return r;\n    toast(`${r.added} row(s) added`+(r.error_count?`, ${r.error_count} skipped:\\n`+r.errors.slice(0,5).join(\'\\n\'):\'\'),r.error_count>0);return r});\n}\n\n/* ---------------------------------------------------------- scan station */\nfunction vScan(){\n  return `<div class="panels"><div class="panel scanbox"><div class="seg bar"><button class="b ${SC.mode==\'receive\'?\'on\':\'\'}" onclick="SC.mode=\'receive\';render()">Receive stock</button><button class="b ${SC.mode==\'sell\'?\'on\':\'\'}" onclick="SC.mode=\'sell\';render()">Sell</button>\n  ${SC.mode==\'sell\'?`<select onchange="SC.sold_by=this.value"><option value="">Sold by…</option>${(L.team||[]).map(x=>`<option ${x==SC.sold_by?\'selected\':\'\'}>${esc(x)}</option>`).join(\'\')}</select>`:\'\'}</div>\n  <input id="scansku" placeholder="${SC.mode==\'receive\'?\'Scan or type a SKU and press Enter to receive 1\':\'Scan or type a SKU and press Enter to sell 1\'}" autocomplete="off" onkeydown="if(event.key==\'Enter\')doScan()">\n  <p class="${SC.bad?\'neg\':\'pos\'}">${esc(SC.msg)}</p><p class="muted">Receive adds 1 unit to a SKU (or creates a new row for you to fill in). Sell logs a sale of 1 unit at the listed price.</p></div>\n  <div class="panel"><h3>Recent scans</h3>${mini(\'<th>Time</th><th>Action</th><th>SKU</th><th>Result</th>\',SCANS.map(s=>`<tr><td>${esc((s.ts||\'\').replace(\'T\',\' \').slice(5,16))}</td><td>${esc(s.action)}</td><td>${esc(s.sku)}</td><td class="wrap ${/^ERROR/.test(s.result)?\'neg\':\'\'}">${esc(s.result)}</td></tr>`).join(\'\'),\'Nothing scanned yet.\')}</div></div>`;\n}\nasync function doScan(){\n  const el=$(\'#scansku\'),sku=el.value.trim();if(!sku)return;el.value=\'\';\n  const r=await api(\'scan\',{mode:SC.mode,sku,sold_by:SC.sold_by});\n  SC.bad=!!r.error;SC.msg=r.error||r.message;\n  await load();\n  if(!r.error&&r.created&&SC.mode==\'receive\')invDlg(r.id);\n  else if(!r.error&&r.needs_price)saleDlg(r.sale_id);\n}\n\n/* ---------------------------------------------------------- tax */\nasync function taxLoad(y){TAX=await api(\'tax\'+(y?\'?year=\'+y:\'\'));if(tab==\'tax\')render()}\nfunction vTax(){\n  const t=TAX;if(!t||t.error)return t&&t.error?`<p class="neg">${esc(t.error)}</p>`:\'<div class="muted">Loading…</div>\';\n  const row=(l,v,b)=>`<tr><td>${b?\'<b>\'+l+\'</b>\':l}</td><td class="num ${b?sgn(v):\'\'}">${b?\'<b>\'+money(v)+\'</b>\':money(v)}</td></tr>`;\n  return `<div class="bar"><label>Tax year</label><select onchange="taxLoad(this.value)">${t.years.map(y=>`<option ${y==t.year?\'selected\':\'\'}>${y}</option>`).join(\'\')}</select><button class="b" onclick="csvExport(\'sales\')">Export sales CSV</button><button class="b" onclick="csvExport(\'receipts\')">Export receipts CSV</button></div>\n  <div class="panel" style="max-width:560px"><h3>${t.year} summary</h3><table>${row(\'Gross sales\',t.gross)}${row(\'Cost of goods sold\',-t.cogs)}${row(\'Platform &amp; other fees\',-t.fees)}${row(\'Shipping costs\',-t.shipping)}${row(\'Other expenses (receipts)\',-t.expenses)}${row(\'Net profit\',t.net,1)}</table>\n  ${t.missing_basis?`<p class="neg">${t.missing_basis} sale(s) have no cost basis — check their inventory items.</p>`:\'\'}<p class="muted">An estimate to help with your records — confirm with a tax professional.</p></div>`;\n}\n\n/* ---------------------------------------------------------- settings */\nfunction vSet(){\n  const s=TS.settings||{};\n  const i=(n,l,v,t=\'text\',x=\'\')=>`<div><label>${l}</label><input id="st_${n}" type="${t}" value="${esc(v??\'\')}" ${x}></div>`;\n  return `<div class="panels"><div class="panel"><h3>Business</h3><div class="grid2" id="stform">${i(\'partner1\',\'Team member 1\',s.partner1)}${i(\'partner2\',\'Team member 2\',s.partner2)}${i(\'aging_days\',\'Aging alert after (days)\',s.aging_days,\'number\',\'min=1\')}${i(\'drop_pct\',\'Suggested price drop (%)\',Math.round((s.drop_pct||0)*1000)/10,\'number\',\'step=0.5 min=0 max=100\')}${i(\'monthly_target\',\'Monthly profit target ($)\',s.monthly_target||\'\',\'number\',\'step=1 min=0\')}${i(\'big_sale\',\'Big-sale alert at profit ($)\',s.big_sale||\'\',\'number\',\'step=1 min=0\')}</div>\n  <label style="display:block;margin-top:8px;color:var(--mute);font-size:12px">Slack webhook URL for big-sale alerts (optional)</label><input id="st_slack_webhook" style="width:100%" value="${esc(s.slack_webhook||\'\')}" placeholder="https://hooks.slack.com/services/…">\n  <label class="cbl" style="margin-top:10px"><input type="checkbox" id="st_auto_update" ${s.auto_update?\'checked\':\'\'}> Download app updates automatically (you choose when to install)</label>\n  <div class="bar" style="margin-top:8px"><button class="b p" onclick="saveSettings()">Save</button></div></div>\n  <div class="panel"><h3>iCloud email</h3><p class="muted">Used to read order emails. Read-only: nothing is changed or deleted in your mailbox.</p><button class="b" onclick="mailSettings()">Email settings…</button></div></div>\n  <div class="panels"><div class="panel"><h3>Platform fees</h3>${mini(\'<th>Platform</th><th class="num">Fee %</th><th class="num">Fixed</th><th></th>\',(TS.fees||[]).map(x=>`<tr><td>${esc(x.platform)}</td><td class="num">${(x.fee_pct*100).toFixed(2)}%</td><td class="num">${money(x.fixed)}</td><td><button class="b" onclick="feeDlg(${q(x.platform)})">Edit</button></td></tr>`).join(\'\'),\'\')}<p><button class="b" onclick="feeDlg()">+ Add platform</button></p></div>\n  <div class="panel"><h3>Currencies (to USD)</h3>${mini(\'<th>Code</th><th class="num">Rate</th><th></th>\',(TS.currencies||[]).map(x=>`<tr><td>${esc(x.code)}</td><td class="num">${x.rate}</td><td>${x.code==\'USD\'?\'\':`<button class="b" onclick="curDlg(${q(x.code)})">Edit</button>`}</td></tr>`).join(\'\'),\'\')}<p><button class="b" onclick="curDlg()">+ Add currency</button></p></div></div>`;\n}\nasync function saveSettings(){\n  const g=n=>$(\'#st_\'+n).value;\n  const r=await api(\'tsettings\',{partner1:g(\'partner1\'),partner2:g(\'partner2\'),aging_days:g(\'aging_days\'),drop_pct:(+g(\'drop_pct\')||0)/100,monthly_target:g(\'monthly_target\'),big_sale:g(\'big_sale\'),slack_webhook:g(\'slack_webhook\').trim(),auto_update:$(\'#st_auto_update\').checked?1:0});\n  if(r.error)return toast(r.error,true);toast(\'Settings saved\');load();\n}\nfunction feeDlg(p){\n  const x=(TS.fees||[]).find(f=>f.platform==p)||{platform:\'\',fee_pct:0,fixed:0};\n  dlg(`<label>Platform</label><input name="platform" value="${esc(x.platform)}" required><label>Fee % of (price + shipping charged)</label><input name="fee_pct" type="number" step="0.01" min="0" max="100" value="${(x.fee_pct*100).toFixed(2)}"><label>Fixed fee per sale ($)</label><input name="fixed" type="number" step="0.01" min="0" value="${x.fixed}">`+(p?`<p><button type="button" class="b" onclick="delFee(${q(p)})">Delete platform</button></p>`:\'\'),\n  fd=>api(\'fees/save\',{platform:fd.platform,fee_pct:(+fd.fee_pct||0)/100,fixed:fd.fixed,old:p||null}));\n}\nasync function delFee(p){if(confirm(\'Delete this platform? Past sales keep their saved name.\')){await api(\'fees/delete\',{platform:p});$(\'#dlg\').close();load()}}\nfunction curDlg(c){\n  const x=(TS.currencies||[]).find(f=>f.code==c)||{code:\'\',rate:1};\n  dlg(`<label>Currency code (3 letters)</label><input name="code" value="${esc(x.code)}" maxlength="3" required ${c?\'readonly\':\'\'}><label>1 unit equals ___ USD</label><input name="rate" type="number" step="0.0001" min="0" value="${x.rate}" required>`+(c?`<p><button type="button" class="b" onclick="delCur(${q(c)})">Delete currency</button></p>`:\'\'),fd=>api(\'currencies/save\',fd));\n}\nasync function delCur(c){if(confirm(\'Delete this currency?\')){const r=await api(\'currencies/delete\',{code:c});if(r.error)return toast(r.error,true);$(\'#dlg\').close();load()}}\nasync function mailSettings(){\n  const s=await api(\'settings\');\n  dlg(`<p class="muted">Use an <b>app-specific password</b> from account.apple.com → Sign-In and Security. It stays on this computer.</p><label>iCloud email</label><input name="email" type="email" value="${esc(s.email)}">`+`<label>App-specific password</label><input name="password" type="password" placeholder="${s.has_password?\'(saved - leave blank to keep)\':\'xxxx-xxxx-xxxx-xxxx\'}">`+\n  `<label>Mail folder(s) to read: <b>*</b> means every folder (comma-separate to pick some, e.g. INBOX, Pokemon Center)</label><input name="folder" list="mailfolders" value="${esc(s.folder)}"><datalist id="mailfolders"></datalist>\n   <p><button type="button" class="b" id="loadfolders">Load my folders</button> <span id="folderstatus" class="muted">Save first if you changed the email or password.</span></p>\n   <p class="muted">Use * to read every folder (Trash and Drafts are skipped). If a folder\'s name contains a store name (like Pokemon Center), every email in it counts as that store, even if forwarded.</p><label>Look back (days, 0 = all time)</label><input name="days" type="number" min="0" value="${esc(s.days)}">`,fd=>api(\'settings\',fd));\n  $(\'#loadfolders\').onclick=async()=>{const st=$(\'#folderstatus\');st.textContent=\'Loading…\';const r=await api(\'mail/folders\');\n    if(!r.ok){st.textContent=r.error;return}st.textContent=r.folders.length+\' folders found: \'+r.folders.join(\', \');$(\'#mailfolders\').innerHTML=r.folders.map(f=>`<option value="${esc(f)}">`).join(\'\')};\n}\n\n/* ---------------------------------------------------------- visual reference */\nfunction vRef(){\n  const g={};(L.visual||[]).forEach(v=>(g[v.group]=g[v.group]||[]).push(v));\n  return `<p class="muted">Quick image searches to help identify sets and eras. Links open in your browser.</p>`+Object.entries(g).map(([k,l])=>`<div class="panel" style="margin-bottom:12px"><h3>${esc(k)}</h3>${mini(\'<th>Era</th><th>Highlights</th><th></th>\',l.map(v=>`<tr><td>${esc(v.era)}</td><td class="wrap">${esc(v.highlights)}</td><td><button class="b" onclick="openUrl(${q(v.url)})">Open images</button></td></tr>`).join(\'\'),\'\')}</div>`).join(\'\');\n}\n\nfunction vOrd(){\n  const rows=data.ord.filter(r=>(r.retailer+r.order_number+r.items.map(i=>i.name).join()).toLowerCase().includes(filter.toLowerCase()));\n  return `<div class="bar">${f()}<button class="b p" onclick="ordDlg()">+ Manual order</button></div><div class="card"><table>\n  <tr><th>Date</th><th>Retailer</th><th>Order #</th><th>Status</th><th>Items</th><th>Total</th><th>Tracking</th><th></th></tr>\n  ${rows.map(o=>`<tr><td>${esc(o.order_date||\'\')}</td><td>${esc(o.retailer)}</td><td>${esc(o.order_number)}</td>\n  <td><span class="pill ${o.status}">${o.status}</span>${o.received?\' <span class="pill pos">in stock</span>\':\'\'}</td>\n  <td class="wrap">${o.items.map(i=>`${i.qty}× ${esc(i.name)}`).join(\'<br>\')||\'<span class="neg">no items</span>\'}</td>\n  <td>${o.total?money(o.total):\'\'}</td><td>${esc(o.tracking)}</td>\n  <td><select onchange="setStatus(${o.id},this.value)">${[\'confirmed\',\'shipped\',\'delivered\',\'cancelled\'].map(s=>`<option ${s==o.status?\'selected\':\'\'}>${s}</option>`).join(\'\')}</select>\n  <button class="b" onclick="itemsDlg(${o.id})">Items</button>\n  ${!o.received&&o.status!=\'cancelled\'&&o.items.length?`<button class="b" onclick="recv(${o.id})">Receive</button>`:\'\'}</td></tr>`).join(\'\')||\'<tr><td class="muted">No orders yet. Click Sync.</td></tr>\'}</table></div>\n  <details class="panel" style="margin-top:12px"${SYNCLOG&&/ERROR|!!/.test(SYNCLOG)?\' open\':\'\'}><summary class="muted">Last email sync log</summary><div class="log" id="log" style="max-height:260px">${esc(SYNCLOG)||\'Nothing synced yet.\'}</div></details>`;\n}\nfunction vRev(){\n  return `<div class="bar"><button class="b p" onclick="parseTestDlg()">Test an email</button><span class="muted">Emails the scraper couldn\'t read land here. Use Test an email to see why, then send me the result.</span></div><div class="card"><table><tr><th>Retailer</th><th>Subject</th><th>Why</th><th></th></tr>\n  ${data.rev.map(r=>`<tr><td>${esc(r.retailer)}</td><td class="wrap">${esc(r.subject)}<div class="muted">${esc((r.snippet||\'\').slice(0,160))}</div></td><td class="wrap">${esc(r.reason)}</td>\n  <td><button class="b" onclick="resolve(${r.id})">Dismiss</button></td></tr>`).join(\'\')||\'<tr><td class="muted">Nothing needs review.</td></tr>\'}</table></div>`;\n}\nfunction groupBySite(list){const g={};list.forEach(r=>(g[r.site]=g[r.site]||[]).push(r));return Object.keys(g).sort().map(k=>[k,g[k]])}\nfunction siteBlock(site,count,inner,extra=\'\'){const o=openSites[site]===true;return `<div class="card" style="margin-bottom:10px"><div style="padding:10px 12px;cursor:pointer;font-weight:600;display:flex;gap:10px;align-items:center" onclick="openSites[${q(site)}]=${!o};render()"><span>${o?\'▾\':\'▸\'} ${esc(site)} <span class="muted">(${count})</span></span>${extra}</div>${o?inner:\'\'}</div>`}\nconst allSites=()=>[...new Set([...SITES,...data.acc.map(a=>a.site),...data.prof.map(p=>p.site)])];\nconst siteList=()=>`<datalist id="sites">${allSites().map(s=>`<option value="${esc(s)}">`).join(\'\')}</datalist>`;\nlet sel={acc:new Set(),prof:new Set()};\nconst chk=(kind,id)=>`<input type="checkbox" ${sel[kind].has(id)?\'checked\':\'\'} onclick="event.stopPropagation();togSel(\'${kind}\',${q(id)},this.checked)">`;\nfunction togSel(kind,id,on){on?sel[kind].add(id):sel[kind].delete(id);updBulk()}\nfunction selAll(kind,ids,on){ids.forEach(i=>on?sel[kind].add(i):sel[kind].delete(i));render()}\nfunction updBulk(){const n=document.getElementById(\'bulkn\');if(n)n.textContent=sel[tab==\'accounts\'?\'acc\':\'prof\'].size}\nconst flag=b=>b?\'<span class="pill pos">yes</span>\':\'<span class="muted">no</span>\';\nfunction bulkBar(kind){\n  const acc=kind==\'acc\';\n  return `<span class="muted"><b id="bulkn">${sel[kind].size}</b> ticked</span>\n  <button class="b" onclick="bulkFlag(\'${kind}\',\'selected\',true)">Mark Valor-selected</button>\n  <button class="b" onclick="bulkFlag(\'${kind}\',\'selected\',false)">Unmark</button>\n  <button class="b" onclick="bulkDel(\'${kind}\')">Delete ticked</button>\n  <button class="b" onclick="sel.${kind}.clear();render()">Clear ticks</button>`;\n}\nasync function bulkFlag(kind,field,val){\n  const ids=[...sel[kind]];if(!ids.length)return toast(\'Tick some rows first.\');\n  if(kind==\'prof\')await api(\'vprofiles/patch\',{ids,changes:{[field]:val}});\n  else for(const [site,list] of groupBySite(data.acc.filter(a=>sel.acc.has(a.id+\'||\'+a.site)))){await api(\'vaccounts/patch\',{site,ids:list.map(a=>a.id),changes:{[field]:val}})}\n  load();\n}\nasync function bulkDel(kind){\n  const ids=[...sel[kind]];if(!ids.length)return toast(\'Tick some rows first.\');\n  if(!confirm(`Delete ${ids.length} ${kind==\'acc\'?\'account(s)\':\'profile(s)\'}? (Rejigged copies of deleted profiles go too.)`))return;\n  if(kind==\'prof\')await api(\'vprofiles/delete\',{ids});\n  else for(const [site,list] of groupBySite(data.acc.filter(a=>sel.acc.has(a.id+\'||\'+a.site)))){await api(\'vaccounts/delete\',{site,ids:list.map(a=>a.id)})}\n  sel[kind].clear();load();\n}\nfunction setByPath(o,path,v){const p=path.split(\'.\');let t=o;p.slice(0,-1).forEach(k=>t=t[k]=t[k]||{});t[p[p.length-1]]=v}\nconst getP=(o,path)=>path.split(\'.\').reduce((a,k)=>a==null?\'\':a[k],o);\nconst sensCat=p=>/^card\\./.test(p)?\'card\':/^(shipping|billing)\\.(addressLine|city|state|zipCode|firstName|lastName)/.test(p)?\'addr\':/^(email|phoneNumber)$/.test(p)?\'contact\':/^(password|proxy)$/.test(p)?\'secret\':\'\';\nconst fld=(path,label,rec,type=\'text\',x=\'\')=>{const c=sensCat(path);return `<div><label>${label}</label><input data-p="${path}" type="${type}" class="${c?\'sens s-\'+c:\'\'}" value="${esc(getP(rec,path)??\'\')}" ${x}></div>`};\nconst cb=(path,label,rec)=>`<label class="cbl"><input type="checkbox" data-p="${path}" data-bool="1" ${getP(rec,path)?\'checked\':\'\'}> ${label}</label>`;\nfunction readForm(base){const rec=JSON.parse(JSON.stringify(base));document.querySelectorAll(\'#form [data-p]\').forEach(e=>{const v=e.dataset.bool?e.checked:(e.type==\'number\'?(e.value===\'\'?0:+e.value):e.value.trim());setByPath(rec,e.dataset.p,v)});return rec}\n\n\n/* ------------------------------ privacy blur */\nconst PRIV_DEF={on:false,addr:true,card:true,contact:true,secret:true};\nlet PRIV=(()=>{try{return {...PRIV_DEF,...JSON.parse(localStorage.getItem(\'valorPriv\')||\'{}\')}}catch(e){return {...PRIV_DEF}}})();\nfunction applyPriv(){\n  document.body.classList.toggle(\'priv-on\',!!PRIV.on);\n  [\'addr\',\'card\',\'contact\',\'secret\'].forEach(k=>document.body.classList.toggle(\'pv-\'+k,!!PRIV[k]));\n  const b=document.getElementById(\'privbtn\');if(b){b.textContent=\'Blur: \'+(PRIV.on?\'on\':\'off\');b.classList.toggle(\'p\',!!PRIV.on)}\n}\nfunction savePriv(){try{localStorage.setItem(\'valorPriv\',JSON.stringify(PRIV))}catch(e){}applyPriv()}\ndocument.addEventListener(\'click\',e=>{const t=e.target.closest&&e.target.closest(\'.sens\');if(t&&document.body.classList.contains(\'priv-on\')&&getComputedStyle(t).filter!==\'none\'){t.classList.add(\'show\');e.stopPropagation()}else if(t&&t.classList.contains(\'show\')){t.classList.remove(\'show\')}},true);\nconst sv=(cat,html)=>`<span class="sens s-${cat}" title="${PRIV.on?\'Click to reveal\':\'\'}">${html}</span>`;\nfunction privBar(){\n  const cb=(k,l)=>`<label class="cbl" style="margin:0"><input type="checkbox" ${PRIV[k]?\'checked\':\'\'} onchange="PRIV[\'${k}\']=this.checked;savePriv()"> ${l}</label>`;\n  return `<div class="privbar ${PRIV.on?\'on\':\'\'}"><label class="cbl" style="margin:0"><input type="checkbox" ${PRIV.on?\'checked\':\'\'} onchange="PRIV.on=this.checked;savePriv();render()"> <b>Blur sensitive info</b></label>${PRIV.on?cb(\'addr\',\'Addresses\')+cb(\'card\',\'Card details\')+cb(\'contact\',\'Email &amp; phone\')+cb(\'secret\',\'Passwords &amp; proxies\')+\'<span class="muted">Click a blurred value to reveal it.</span>\':\'<span class="muted">Hide addresses, cards, emails and passwords while screen-sharing or streaming.</span>\'}</div>`;\n}\nconst addrBlock=(a,sameLabel)=>{\n  if(sameLabel)return `<span class="pill">same as shipping</span>`;\n  const l1=[a.addressLine1,a.addressLine2].filter(Boolean).join(\', \');\n  const l2=[a.city,[a.state,a.zipCode].filter(Boolean).join(\' \')].filter(Boolean).join(\', \');\n  if(!l1&&!l2)return \'<span class="muted">—</span>\';\n  return `<div class="addr">${sv(\'addr\',`${esc(l1)}<br><small>${esc(l2)}${a.countryCode&&a.countryCode!=\'US\'?\' · \'+esc(a.countryCode):\'\'}</small>`)}</div>`;\n};\n\n/* ------------------------------ accounts */\nfunction vAcc(){\n  const rows=data.acc.filter(r=>(r.site+r.rec.email+r.rec.proxy).toLowerCase().includes(filter.toLowerCase()));\n  return `${privBar()}<div class="bar">${f()}<button class="b p" onclick="accDlg()">+ Add account</button><button class="b" onclick="accImport()">Import Valor file</button><button class="b" onclick="accExport()">Export Valor file</button><span class="muted">${rows.length} accounts</span></div>\n  <div class="bar">${bulkBar(\'acc\')}</div>\n  ${groupBySite(rows).map(([s,l])=>siteBlock(s,l.length,`<table><tr><th><input type="checkbox" onclick="selAll(\'acc\',${q(l.map(a=>a.id+\'||\'+a.site))},this.checked)"></th><th>Email</th><th>Password</th><th>Proxy</th><th>Session</th><th>Valor-selected</th><th></th></tr>${l.map(a=>`<tr><td>${chk(\'acc\',a.id+\'||\'+a.site)}</td><td>${sv(\'contact\',esc(a.rec.email))}</td><td>${a.rec.password?sv(\'secret\',`<span class="muted" style="cursor:pointer" onclick="if(!document.body.classList.contains(\'priv-on\')){this.textContent=this.dataset.p}" data-p="${esc(a.rec.password)}">${PRIV.on&&PRIV.secret?esc(a.rec.password):\'•••••• (click)\'}</span>`):\'\'}</td><td>${a.rec.proxy?sv(\'secret\',esc(a.rec.proxy)):\'\'}</td><td>${flag(a.rec.session)}</td><td>${flag(a.rec.selected)}</td><td><button class="b" onclick="accDlg(${q(a.site)},${q(a.id)})">Edit</button></td></tr>`).join(\'\')}</table>`)).join(\'\')||\'<div class="card"><table><tr><td class="muted">No accounts yet. Use Import Valor file.</td></tr></table></div>\'}${siteList()}`;\n}\nfunction accDlg(site,id){\n  const a=id?data.acc.find(x=>x.id==id&&x.site==site):null;const rec=a?a.rec:{id:\'\',email:\'\',password:\'\',proxy:\'\',session:false,selected:false};\n  dlg(`<div><label>Website</label><input id="accsite" list="sites" value="${esc(a?a.site:\'\')}" required></div><div class="grid2">`+fld(\'email\',\'Account email\',rec,\'text\',\'required\')+fld(\'password\',\'Password\',rec)+fld(\'proxy\',\'Proxy (host:port:user:pass)\',rec)+fld(\'id\',\'ID (normally = email)\',rec)+`</div>`+cb(\'session\',\'Keep session\',rec)+cb(\'selected\',\'Selected in Valor\',rec)+(a?`<p><button type="button" class="b" onclick="delAcc(${q(a.site)},${q(a.id)})">Delete account</button></p>`:\'\'),\n  async()=>{const r=readForm(rec);return api(\'vaccounts/save\',{site:$(\'#accsite\').value,rec:r,old_id:a?a.id:null,old_email:a?a.rec.email:null})});\n}\nasync function delAcc(site,id){if(confirm(\'Delete this account?\')){await api(\'vaccounts/delete\',{site,ids:[id]});$(\'#dlg\').close();load()}}\nfunction accImport(){\n  dlg(`<p class="muted">Choose an accounts file exported from Valor. Existing accounts with the same ID are updated; nothing else is touched.</p><label>Valor accounts file (.json)</label><input type="file" accept=".json" id="impfile" required>`+inp(\'site\',\'Website (leave blank to use the name inside the file)\',\'\')+`<label class="cbl"><input type="checkbox" id="impreplace"> Replace all existing accounts for that website</label>`,\n  async fd=>{const f=$(\'#impfile\').files[0];if(!f)return{error:\'Choose a file\'};const r=await api(\'vaccounts/import\',{text:await f.text(),site:fd.site,replace:$(\'#impreplace\').checked});if(!r.error)toast(`${r.site}: ${r.added} added, ${r.updated} updated`);return r});\n}\nfunction accExport(){\n  const sites=[...new Set(data.acc.map(a=>a.site))].sort();if(!sites.length)return toast(\'No accounts to export yet.\');\n  dlg(`<label>Website</label><select id="exsite">${sites.map(s=>`<option>${esc(s)}</option>`).join(\'\')}</select><label class="cbl"><input type="checkbox" id="exsel"> Only accounts marked Valor-selected</label><p class="muted">Creates a file in the same format Valor exports. Import it in Valor\'s Accounts page.</p>`,\n  async()=>{const fn=`valor_accounts_${$(\'#exsite\').value.replace(/\\W+/g,\'_\')}.json`;const r=await api(\'vaccounts/export\',{site:$(\'#exsite\').value,selected_only:$(\'#exsel\').checked,filename:fn});if(r.error)return r;if(!window.pywebview)saveText(fn,r.json);toast(r.count+\' accounts exported to:\\n\'+r.saved_to);return r});\n}\nfunction saveText(name,text){const a=document.createElement(\'a\');a.href=URL.createObjectURL(new Blob([text],{type:\'application/json\'}));a.download=name;document.body.appendChild(a);a.click();a.remove()}\n\n/* ------------------------------ profiles */\nconst mask=n=>n?\'•••• \'+String(n).replace(/\\D/g,\'\').slice(-4):\'\';\nfunction vProf(){\n  const t=filter.toLowerCase();\n  const rows=data.prof.filter(r=>!t||(r.site+r.rec.name+r.rec.email+r.rec.shipping.addressLine1+r.rec.shipping.addressLine2+r.rec.shipping.city+r.rec.shipping.zipCode+r.rec.shipping.firstName+r.rec.shipping.lastName).toLowerCase().includes(t));\n  return `${privBar()}<div class="bar">${f()}<button class="b p" onclick="profDlg()">+ Add profile</button><button class="b" onclick="profImport()">Import Valor file</button><button class="b" onclick="profExport()">Export Valor file</button><button class="b" onclick="massEditDlg()">Mass edit…</button><button class="b" onclick="massEditDlg(\'Billing\')">Mass edit billing…</button><button class="b" onclick="bulkAddrDlg()">Change addresses…</button><span class="muted">${rows.length} profiles</span></div>\n  <div class="bar">${bulkBar(\'prof\')}</div>\n  ${groupBySite(rows).map(([s,l])=>siteBlock(s,l.length,`<div style="overflow:auto"><table><tr><th><input type="checkbox" onclick="selAll(\'prof\',${q(l.map(p=>p.id))},this.checked)"></th><th>Profile</th><th>Shipping address</th><th>Billing address</th><th>Contact</th><th>Card</th><th>Valor-sel.</th><th></th></tr>${l.map(p=>{const r=p.rec,sh=r.shipping,bi=r.billing||{};const same=r.billingSameAsShipping;return `<tr><td>${chk(\'prof\',p.id)}</td><td class="wrap" style="min-width:120px">${p.group_id?\'<span class="muted">↳ </span>\':\'\'}<b>${esc(r.name)}</b></td><td class="wrap"><div>${sv(\'addr\',esc((sh.firstName+\' \'+sh.lastName).trim()))}</div>${addrBlock(sh)}</td><td class="wrap">${same?`<span class="pill">same as shipping</span>`:`<div>${sv(\'addr\',esc((bi.firstName+\' \'+bi.lastName).trim()))}</div>${addrBlock(bi)}`}</td><td class="wrap">${sv(\'contact\',esc(r.email))}<br>${sv(\'contact\',`<small class="muted">${esc(r.phoneNumber)}</small>`)}</td><td class="wrap">${sv(\'card\',`${esc(r.card.type||\'card\')} ${mask(r.card.number)}<br><small class="muted">${esc(r.card.expiration||\'\')}</small>`)}</td><td>${flag(r.selected)}</td><td style="white-space:normal;min-width:130px"><button class="b" onclick="profDlg(${q(p.id)})">Edit</button>${p.group_id?\'\':` <button class="b" onclick="jigDlg(${q(p.id)})">Rejig</button>`}</td></tr>`}).join(\'\')}</table></div>`)).join(\'\')||\'<div class="card"><table><tr><td class="muted">No profiles yet. Use Import Valor file.</td></tr></table></div>\'}${siteList()}`;\n}\nconst BLANK={name:\'\',email:\'\',phoneNumber:\'\',billingSameAsShipping:true,oneCheckout:false,quickTask:false,card:{holder:\'\',number:\'\',expiration:\'\',cvv:\'\',type:\'\'},\n  shipping:{firstName:\'\',lastName:\'\',addressLine1:\'\',addressLine2:\'\',city:\'\',countryName:\'United States\',countryCode:\'US\',state:\'\',zipCode:\'\'},\n  billing:{firstName:\'\',lastName:\'\',addressLine1:\'\',addressLine2:\'\',city:\'\',countryName:\'United States\',countryCode:\'US\',state:\'\',zipCode:\'\'},id:\'\',totalSpent:0,selected:false};\nconst addrFields=(k,rec)=>fld(k+\'.firstName\',\'First name\',rec)+fld(k+\'.lastName\',\'Last name\',rec)+fld(k+\'.addressLine1\',\'Address line 1\',rec)+fld(k+\'.addressLine2\',\'Address line 2\',rec)+fld(k+\'.city\',\'City\',rec)+fld(k+\'.state\',\'State\',rec)+fld(k+\'.zipCode\',\'ZIP / postal code\',rec)+fld(k+\'.countryCode\',\'Country code (US)\',rec)+fld(k+\'.countryName\',\'Country name\',rec);\nfunction profDlg(id){\n  const p=id?data.prof.find(x=>x.id==id):null;\n  const rec=p?p.rec:JSON.parse(JSON.stringify(BLANK));\n  const hasExtra=[\'personalCustomsCode\',\'pinCode\',\'idNumber\',\'birthday\'].some(k=>k in rec);\n  dlg(`<div class="grid2"><div><label>Website</label><input id="profsite" list="sites" value="${esc(p?p.site:\'\')}" required></div>`+fld(\'name\',\'Profile name\',rec,\'text\',\'required\')+fld(\'email\',\'Email\',rec)+fld(\'phoneNumber\',\'Phone number\',rec)+`</div>\n  <div style="margin:8px 0">${cb(\'billingSameAsShipping\',\'Billing same as shipping\',rec)}${cb(\'oneCheckout\',\'One checkout\',rec)}${cb(\'quickTask\',\'Quick task\',rec)}${cb(\'selected\',\'Selected in Valor\',rec)}</div>\n  <fieldset><legend>Card</legend><div class="grid2">${fld(\'card.holder\',\'Name on card\',rec)}${fld(\'card.number\',\'Card number\',rec,\'text\',\'autocomplete=off\')}${fld(\'card.expiration\',\'Expiration (MM/YY)\',rec)}${fld(\'card.cvv\',\'CVV\',rec,\'text\',\'autocomplete=off\')}\n  <div><label>Card type</label><select data-p="card.type">${[\'\',\'visa\',\'mastercard\',\'amex\',\'discover\'].map(t=>`<option value="${t}" ${rec.card.type==t?\'selected\':\'\'}>${t||\'(auto-detect)\'}</option>`).join(\'\')}</select></div>${fld(\'totalSpent\',\'Total spent\',rec,\'number\',\'step=0.01\')}</div></fieldset>\n  <fieldset><legend>Shipping</legend><div class="grid2">${addrFields(\'shipping\',rec)}</div></fieldset>\n  <fieldset><legend>Billing</legend><div class="grid2">${addrFields(\'billing\',rec)}</div></fieldset>\n  <fieldset><legend>Other (optional)</legend><div class="grid2">${[\'personalCustomsCode\',\'pinCode\',\'idNumber\',\'birthday\'].map(k=>fld(k,{personalCustomsCode:\'Personal customs code\',pinCode:\'PIN code\',idNumber:\'ID number\',birthday:\'Birthday\'}[k],rec)).join(\'\')}</div></fieldset>`\n  +(p?`<p><button type="button" class="b" onclick="delProf(${q(p.id)})">Delete profile</button></p>`:\'\'),\n  async()=>{const r=readForm(rec);\n    if(r.billingSameAsShipping&&(!p||!p.rec.billingSameAsShipping)){r.billing={...r.billing,...r.shipping}}\n    if(!r.card.type&&r.card.number){const n=r.card.number.replace(/\\D/g,\'\');r.card.type=/^4/.test(n)?\'visa\':/^(5[1-5]|2[2-7])/.test(n)?\'mastercard\':/^3[47]/.test(n)?\'amex\':/^(6011|65)/.test(n)?\'discover\':\'\'}\n    return api(\'vprofiles/save\',{site:$(\'#profsite\').value,rec:r,id:p?p.id:null,group_id:p?p.group_id:null})},\'wide\');\n}\nasync function delProf(id){if(confirm(\'Delete this profile (and its rejigged copies)?\')){await api(\'vprofiles/delete\',{ids:[id]});$(\'#dlg\').close();load()}}\nfunction profImport(){\n  dlg(`<p class="muted">Choose a profiles file exported from Valor. Profiles with the same ID are updated; every field in the file is kept exactly as-is.</p><label>Valor profiles file (.json)</label><input type="file" accept=".json" id="impfile" required><label>Website these profiles are for</label><input name="site" list="sites" required placeholder="e.g. Pokemon Center US"><label class="cbl"><input type="checkbox" id="impreplace"> Replace all existing profiles for that website</label>`+siteList(),\n  async fd=>{const f=$(\'#impfile\').files[0];if(!f)return{error:\'Choose a file\'};const r=await api(\'vprofiles/import\',{text:await f.text(),site:fd.site,replace:$(\'#impreplace\').checked});if(!r.error)toast(`${r.added} added, ${r.updated} updated`);return r});\n}\nfunction profExport(){\n  const sites=[...new Set(data.prof.map(p=>p.site))].sort();if(!sites.length)return toast(\'No profiles to export yet.\');\n  dlg(`<label>Website</label><select id="exsite"><option value="">All websites</option>${sites.map(s=>`<option>${esc(s)}</option>`).join(\'\')}</select>\n  <label class="cbl"><input type="checkbox" id="exsel"> Only profiles marked Valor-selected</label><label class="cbl"><input type="checkbox" id="exo" checked> Include original profiles</label><label class="cbl"><input type="checkbox" id="exj" checked> Include rejigged copies</label><p class="muted">Creates a file in the same format Valor exports. Import it in Valor\'s Profiles page.</p>`,\n  async()=>{const fn=\'valor_profiles\'+($(\'#exsite\').value?\'_\'+$(\'#exsite\').value.replace(/\\W+/g,\'_\'):\'\')+\'.json\';const r=await api(\'vprofiles/export\',{site:$(\'#exsite\').value,selected_only:$(\'#exsel\').checked,include_originals:$(\'#exo\').checked,include_jigs:$(\'#exj\').checked,filename:fn});if(r.error)return r;if(!window.pywebview)saveText(fn,r.json);toast(r.count+\' profiles exported to:\\n\'+r.saved_to);return r});\n}\nfunction jigDlg(id){\n  const p=data.prof.find(x=>x.id==id);const sh=p.rec.shipping;const existing=data.prof.filter(x=>x.group_id==id).length;\n  const run=async save=>{const fd=Object.fromEntries(new FormData($(\'#form\')));const r=await api(\'vprofiles/jig\',{id,count:+fd.count,use_units:!!fd.use_units,seed:fd.seed,save,replace:true});if(r.error){toast(r.error);return false}\n    $(\'#jigout\').innerHTML=`<b>${r.variants.length} of ${fd.count} available</b><br>`+r.variants.map(v=>esc(v.addressLine1)+(v.addressLine2?\', \'+esc(v.addressLine2):\'\')).join(\'<br>\');return true};\n  dlg(`<b>${esc(p.rec.name)}</b><div class="muted">${esc(sh.addressLine1)} ${esc(sh.addressLine2)}, ${esc(sh.city)} ${esc(sh.state)} ${esc(sh.zipCode)}</div><p class="muted">Makes copies of this profile with alternate spellings of the same address (St/Street, N/North, Apt/Unit/#). City, state and ZIP never change. ${existing?`<b>Saving replaces its ${existing} existing copies.</b>`:\'\'}</p>`+inp(\'count\',\'How many copies\',10,\'number\',\'min=1 max=200\')+`<label class="cbl"><input type="checkbox" name="use_units" checked> Add unit lines (Apt 3, #B…) when there is no line 2</label>`+inp(\'seed\',\'Seed (optional; same seed = same result)\',\'\')+`<p><button type="button" class="b" id="prevbtn">Preview</button></p><div id="jigout" class="log" style="max-height:180px"></div>`,\n  async()=>{const ok=await run(true);return ok?null:{error:\'No copies were saved\'}});\n  $(\'#prevbtn\').onclick=()=>run(false);\n}\n\nfunction fieldDefs(){return [\n [\'Contact\',[[\'email\',\'Email\'],[\'phoneNumber\',\'Phone number\']]],\n [\'Switches\',[[\'billingSameAsShipping\',\'Billing same as shipping\',\'bool\'],[\'oneCheckout\',\'One checkout\',\'bool\'],[\'quickTask\',\'Quick task\',\'bool\'],[\'selected\',\'Selected in Valor\',\'bool\']]],\n [\'Card\',[[\'card.holder\',\'Name on card\'],[\'card.number\',\'Card number\'],[\'card.expiration\',\'Expiration (MM/YY)\'],[\'card.cvv\',\'CVV\'],[\'card.type\',\'Card type\',\'type\']]],\n [\'Shipping\',addrKeys(\'shipping\')],\n [\'Billing\',addrKeys(\'billing\')],\n [\'Other\',[[\'personalCustomsCode\',\'Personal customs code\'],[\'pinCode\',\'PIN code\'],[\'idNumber\',\'ID number\'],[\'birthday\',\'Birthday\'],[\'totalSpent\',\'Total spent\',\'num\']]]]}\nfunction addrKeys(k){return [[\'firstName\',\'First name\'],[\'lastName\',\'Last name\'],[\'addressLine1\',\'Address line 1\'],[\'addressLine2\',\'Address line 2\'],[\'city\',\'City\'],[\'state\',\'State\'],[\'zipCode\',\'ZIP\'],[\'countryCode\',\'Country code\'],[\'countryName\',\'Country name\']].map(([a,b])=>[k+\'.\'+a,b])}\nfunction massRow([p,l,t]){\n  const inpt=t==\'bool\'?`<select data-v="${p}"><option value="true">On</option><option value="false">Off</option></select>`:t==\'type\'?`<select data-v="${p}">${[\'visa\',\'mastercard\',\'amex\',\'discover\'].map(x=>`<option>${x}</option>`).join(\'\')}</select>`:`<input data-v="${p}" type="${t==\'num\'?\'number\':\'text\'}" ${t==\'num\'?\'step=0.01\':\'\'}>`;\n  return `<div class="mrow"><label class="cbl"><input type="checkbox" data-c="${p}" onchange="this.closest(\'.mrow\').classList.toggle(\'on\',this.checked)"> ${l}</label>${inpt}</div>`}\nfunction massEditDlg(only){\n  const sites=[...new Set(data.prof.map(p=>p.site))].sort();if(!sites.length)return toast(\'No profiles yet.\');\n  const ticked=sel.prof.size;\n  const groups=fieldDefs().filter(g=>!only||g[0]==only);\n  dlg(`<p class="muted">Tick each field you want to change, type the new value, and it is set on every profile in scope. Fields you don\'t tick are left alone. Export first if unsure; there is no undo.</p>\n  <div class="grid2"><div><label>Website</label><select id="mesite">${sites.map(s=>`<option>${esc(s)}</option>`).join(\'\')}</select></div>\n  <div><label>Apply to</label><select id="mescope"><option value="all">All profiles for that website</option><option value="ticked" ${ticked?\'selected\':\'\'}>Only the ${ticked} ticked rows</option><option value="orig">Original profiles only (no rejigged copies)</option></select></div></div>\n  ${groups.map(([g,rows])=>`<fieldset><legend>${g}</legend><div class="grid2">${rows.map(massRow).join(\'\')}</div></fieldset>`).join(\'\')}`,\n  async()=>{const changes={};document.querySelectorAll(\'#form [data-c]\').forEach(c=>{if(!c.checked)return;const el=document.querySelector(`#form [data-v="${c.dataset.c}"]`);let v=el.value;if(v===\'true\')v=true;else if(v===\'false\')v=false;else if(el.type==\'number\')v=v===\'\'?0:+v;changes[c.dataset.c]=typeof v==\'string\'?v.trim():v});\n    if(!Object.keys(changes).length)return{error:\'Tick at least one field to change\'};\n    const site=$(\'#mesite\').value,sc=$(\'#mescope\').value;let ids=data.prof.filter(p=>p.site==site&&(sc==\'all\'||(sc==\'orig\'&&!p.group_id)||(sc==\'ticked\'&&sel.prof.has(p.id)))).map(p=>p.id);\n    if(!ids.length)return{error:\'No profiles in that scope\'};\n    if(changes[\'billing.addressLine1\']!==undefined||Object.keys(changes).some(k=>k.startsWith(\'billing.\')))if(!(\'billingSameAsShipping\' in changes)&&confirm(\'You are changing billing fields. Also switch off “Billing same as shipping” on these profiles so the new billing is used?\'))changes.billingSameAsShipping=false;\n    if(!confirm(`Change ${Object.keys(changes).length} field(s) on ${ids.length} profiles?`))return{error:\'Cancelled\'};\n    const r=await api(\'vprofiles/patch\',{ids,changes});if(!r.error)toast(r.updated+\' profiles updated\');return r},\'wide\');\n}\nfunction vLim(){\n  return `<div class="bar"><button class="b p" onclick="limDlg()">+ Add limit</button><span class="muted">Track units bought per retailer against the store\'s posted limit. Counts come from your orders (cancelled ones excluded).</span></div><div class="card"><table><tr><th>Retailer</th><th>Product contains</th><th>Limit</th><th>Window</th><th>Bought</th><th>Left</th><th></th></tr>\n  ${data.lim.map(l=>`<tr><td>${esc(l.retailer)}</td><td>${esc(l.product)}</td><td>${l.max_qty}</td><td>${l.window_days?l.window_days+\' days\':\'all time\'}</td><td class="${l.over?\'neg\':\'\'}">${l.bought}</td><td class="${l.over?\'neg\':\'pos\'}">${l.over?\'over limit\':l.remaining}</td><td><button class="b" onclick="limDlg(${l.id})">Edit</button></td></tr>`).join(\'\')||\'<tr><td class="muted">No limits yet. Add one, e.g. Target / Elite Trainer Box / 2.</td></tr>\'}</table></div>`;\n}\nfunction limDlg(id){\n  const l=data.lim.find(x=>x.id==id)||{retailer:\'\',product:\'\',max_qty:1,window_days:0};\n  dlg(`<label>Retailer</label><input name="retailer" list="sites" value="${esc(l.retailer)}" required>`+inp(\'product\',\'Product name contains\',l.product,\'text\',\'required\')+inp(\'max_qty\',\'Max units\',l.max_qty,\'number\',\'min=1\')+inp(\'window_days\',\'Window in days (0 = all time)\',l.window_days,\'number\',\'min=0\')+siteList()+(id?`<p><button type="button" class="b" onclick="delLim(${id})">Delete</button></p>`:\'\'),\n  fd=>api(\'limits/save\',{...fd,id}));\n}\nasync function delLim(id){if(confirm(\'Delete this limit?\')){await api(\'limits/delete\',{id});$(\'#dlg\').close();load()}}\nlet UPD={info:null,status:{phase:\'idle\'},msg:\'\',busy:false,timer:null};\nfunction vUpd(){\n  const i=UPD.info,s=UPD.status,pct=s.total?Math.round(100*s.done/s.total):0,mb=n=>(n/1048576).toFixed(1)+\' MB\';\n  const ph=s.phase;\n  return `<div class="card" style="padding:16px;max-width:720px"><h3 style="margin:0 0 6px">Updates</h3>\n  <p>Installed build: <b>${s.build??\'?\'}</b>${i&&i.ok?` &nbsp;·&nbsp; Latest on GitHub: <b>${i.latest}</b>`:\'\'}</p>\n  ${UPD.msg?`<p class="${i&&i.ok===false?\'neg\':\'\'}">${esc(UPD.msg)}</p>`:\'\'}\n  ${i&&i.ok&&i.update?`<p style="color:var(--ok)"><b>A new version is available.</b></p>${i.notes?`<div class="log" style="max-height:80px">${esc(i.notes)}</div>`:\'\'}`:\'\'}\n  ${ph==\'downloading\'?`<div style="background:var(--line);border-radius:6px;height:12px;margin:10px 0"><div style="width:${pct}%;height:12px;border-radius:6px;background:var(--acc)"></div></div><p class="muted">Downloading… ${mb(s.done)} of ${mb(s.total)} (${pct}%)</p>`:\'\'}\n  ${ph==\'ready\'?`<p style="color:var(--ok)">Download finished. Click Install to update. The app will close, install over the old files, and reopen by itself. Your data is kept.</p>`:\'\'}\n  ${ph==\'installing\'?\'<p>Installing… the app will reopen in a few seconds.</p>\':\'\'}\n  ${ph==\'error\'?`<p class="neg">${esc(s.error)}</p>`:\'\'}\n  <div class="bar"><button class="b" onclick="checkUpdate()" ${UPD.busy||ph==\'downloading\'?\'disabled\':\'\'}>Check for updates</button>\n  ${i&&i.ok&&i.update&&ph!=\'downloading\'&&ph!=\'ready\'&&ph!=\'installing\'?`<button class="b p" onclick="startUpdate()">Download update</button>`:\'\'}\n  ${ph==\'ready\'?`<button class="b p" onclick="installUpdate()">Install &amp; restart</button>`:\'\'}</div>\n  <details style="margin-top:12px"><summary class="muted">Private repository? Add a GitHub token</summary>\n  <p class="muted">Only needed if your GitHub repo is private. Create a fine-grained token on GitHub (Settings → Developer settings) with read-only "Contents" access to this repo, and paste it here. It is stored only on this PC.</p>\n  <input id="ghtoken" type="password" placeholder="${s.has_token?\'(saved - paste to replace)\':\'github_pat_…\'}" style="width:100%"><p><button class="b" onclick="saveToken()">Save token</button></p></details></div>`;\n}\nasync function pollUpd(){\n  UPD.status=await api(\'update/status\');updBadge();if(tab==\'updates\')render();\n  clearTimeout(UPD.timer);if(UPD.status.phase==\'downloading\')UPD.timer=setTimeout(pollUpd,500);\n}\nasync function checkUpdate(quiet){\n  UPD.busy=true;UPD.msg=\'Checking…\';if(tab==\'updates\')render();\n  const r=await api(\'update/check\');UPD.busy=false;UPD.info=r;\n  UPD.msg=!r.ok?r.error:r.update?\'\':\'You are up to date.\';\n  await pollUpd();updBadge();return r;\n}\nasync function startUpdate(){const i=UPD.info;UPD.msg=\'\';const r=await api(\'update/download\',{url:i.url,size:i.size});if(!r.ok){UPD.msg=r.error;render();return}pollUpd()}\nasync function installUpdate(){if(!confirm(\'Install now? The app will close and reopen by itself.\'))return;const r=await api(\'update/install\',{});if(!r.ok){UPD.msg=r.error;toast(r.error,true);render()}else{UPD.status.phase=\'installing\';render()}}\nasync function saveToken(){await api(\'update/token\',{token:$(\'#ghtoken\').value});UPD.msg=\'Token saved.\';await pollUpd();checkUpdate()}\nlet IB={folder:\'\',folders:[],list:null,open:null,q:\'\',err:\'\',loading:false};\nfunction vInbox(){\n  if(!IB.list&&!IB.loading&&!IB.err)setTimeout(()=>ibLoad(),0);\n  const l=IB.list,o=IB.open;\n  return `<div class="bar"><select id="ibfolder" onchange="IB.folder=this.value;IB.open=null;ibLoad()">${(IB.folders.length?IB.folders:[IB.folder||\'INBOX\']).map(f=>`<option ${f==(IB.folder||\'INBOX\')?\'selected\':\'\'}>${esc(f)}</option>`).join(\'\')}</select>\n  <input id="ibq" placeholder="Search subject, sender, text…" value="${esc(IB.q)}" onkeydown="if(event.key==\'Enter\'){IB.q=this.value;ibLoad()}" style="min-width:220px"><button class="b" onclick="IB.q=$(\'#ibq\').value;ibLoad()">Search</button><button class="b" onclick="IB.q=\'\';ibLoad()">Refresh</button>\n  <span class="muted">${IB.loading?\'Loading…\':l?`Showing ${l.messages.length} of ${l.total} (newest first). Read-only: nothing is changed or deleted.`:\'\'}</span></div>\n  ${IB.err?`<div class="card" style="padding:14px"><p class="neg">${esc(IB.err)}</p><p class="muted">Check Settings: iCloud email, app-specific password and folder name.</p></div>`:`\n  <div style="display:grid;grid-template-columns:minmax(280px,380px) 1fr;gap:10px;align-items:start" class="ibgrid">\n  <div class="card" style="max-height:70vh;overflow:auto">${l?l.messages.map(m=>`<div class="ibrow ${o&&o.uid==m.uid?\'on\':\'\'}" onclick="ibOpen(\'${m.uid}\')"><div style="font-weight:${m.unread?700:500}">${esc(m.subject)}</div><div class="muted" style="font-size:12px">${esc(m.from)}</div><div class="muted" style="font-size:12px">${esc(m.date.replace(\'T\',\' \').slice(0,16))}</div></div>`).join(\'\')||\'<div class="muted" style="padding:12px">No emails.</div>\':\'\'}</div>\n  <div class="card" style="padding:14px;max-height:70vh;overflow:auto">${o?ibView(o):\'<span class="muted">Select an email to read it.</span>\'}</div></div>`}`;\n}\nfunction ibView(o){\n  if(o.loading)return \'Loading…\';\n  if(o.error)return `<span class="neg">${esc(o.error)}</span>`;\n  const p=o.parsed;\n  return `<h3 style="margin:0 0 4px">${esc(o.subject)}</h3><div class="muted" style="font-size:12px">From ${esc(o.from)}<br>To ${esc(o.to)} · ${esc(o.date.replace(\'T\',\' \'))}</div>\n  <div style="margin:10px 0;padding:8px 10px;border:1px solid var(--line);border-radius:8px">${p?`<b>Scraper reads this as:</b> ${esc(p.retailer)} order <b>${esc(p.order_number)}</b> — ${p.status}${p.total?`, total ${money(p.total)}`:\'\'}${p.tracking?`, tracking ${esc(p.tracking)}`:\'\'}<br>${p.items.length?p.items.map(i=>`${i.qty}× ${esc(i.name)} (${money(i.price)})`).join(\'<br>\'):\'<span class="neg">no items found</span>\'}`:`<b>Scraper:</b> <span class="neg">${esc(o.reason)}</span>`}\n  <div style="margin-top:6px">${p?`<button class="b p" onclick="ibApply(\'${o.uid}\')">Import into orders</button> `:\'\'}<button class="b" onclick="ibTest()">Copy into Test tool</button></div></div>\n  <div class="bar"><button class="b" onclick="IB.view=\'text\';render()">Text</button>${o.html?`<button class="b" onclick="IB.view=\'html\';render()">Formatted</button>`:\'\'}</div>\n  ${IB.view==\'html\'&&o.html?`<iframe sandbox="" style="width:100%;height:55vh;border:1px solid var(--line);border-radius:8px;background:#fff" srcdoc="${esc(`<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:"><base target="_blank">`+o.html)}"></iframe>`:`<pre style="white-space:pre-wrap;font:13px/1.45 ui-monospace,monospace">${esc(o.text)}</pre>`}`;\n}\nasync function ibLoad(){\n  IB.loading=true;IB.err=\'\';render();\n  if(!IB.folders.length){const f=await api(\'mail/folders\');if(f.ok){IB.folders=f.folders;if(!IB.folder)IB.folder=f.folders.includes(\'INBOX\')?\'INBOX\':f.folders[0]}else{IB.err=f.error;IB.loading=false;IB.list=null;render();return}}\n  const r=await api(\'inbox/list?folder=\'+encodeURIComponent(IB.folder||\'INBOX\')+\'&limit=60&q=\'+encodeURIComponent(IB.q));\n  IB.loading=false;if(!r.ok){IB.err=r.error;IB.list=null}else IB.list=r;render();\n}\nasync function ibOpen(uid){\n  IB.open={uid,loading:true};IB.view=\'text\';render();\n  const r=await api(\'inbox/message?folder=\'+encodeURIComponent(IB.folder||\'INBOX\')+\'&uid=\'+uid);\n  IB.open=r.ok?r:{uid,error:r.error};if(r.ok&&r.html&&!r.parsed)IB.view=\'text\';render();\n}\nasync function ibApply(uid){const r=await api(\'inbox/apply\',{folder:IB.folder||\'INBOX\',uid});toast(r.ok?\'Done: \'+r.outcome:r.error);load()}\nfunction ibTest(){const o=IB.open;parseTestDlg();$(\'#form [name=sender]\').value=o.from;$(\'#form [name=subject]\').value=o.subject;$(\'#form [name=body]\').value=o.text}\nfunction parseTestDlg(){\n  dlg(`<p class="muted">Paste an email to see exactly how the scraper reads it. Copy the sender, subject and body from the email.</p>`+inp(\'sender\',\'From (sender address)\',\'\')+inp(\'subject\',\'Subject\',\'\')+`<label>Body</label><textarea name="body" rows="9" style="width:100%"></textarea><div id="ptres" class="log" style="max-height:200px"></div>`,\n  async fd=>{const r=await api(\'parse_test\',fd);$(\'#ptres\').textContent=r.event?\'OK. Read as:\\n\'+JSON.stringify(r.event,null,2):\'NOT PARSED: \'+r.reason;return {error:r.event?\'Looks good. This is only a test; nothing was saved.\':\'Not parsed: \'+r.reason}},\'wide\');\n}\nfunction bulkAddrDlg(){\n  const sites=[...new Set(data.prof.map(p=>p.site))].sort();if(!sites.length)return toast(\'No profiles yet.\');\n  const ticked=sel.prof.size;\n  const a={addressLine1:\'\',addressLine2:\'\',city:\'\',state:\'\',zipCode:\'\',countryCode:\'US\',countryName:\'United States\'};\n  dlg(`<p class="muted">Moves profiles to a new address. Choose billing only to leave shipping untouched. No backup is made, so export first if unsure.</p><label>Website</label><select id="basite">${sites.map(s=>`<option>${esc(s)}</option>`).join(\'\')}</select>\n  <label>Which address</label><select id="batarget"><option value="both">Shipping (billing follows if “same as shipping”)</option><option value="shipping">Shipping only</option><option value="billing">Billing only</option></select><label>Apply to</label><select id="bascope"><option value="all">All profiles for that website</option><option value="ticked" ${ticked?\'selected\':\'\'}>Only the ${ticked} ticked rows</option></select><div class="grid2">${fld(\'addressLine1\',\'Address line 1\',a)}${fld(\'addressLine2\',\'Address line 2\',a)}${fld(\'city\',\'City\',a)}${fld(\'state\',\'State\',a)}${fld(\'zipCode\',\'ZIP\',a)}${fld(\'countryCode\',\'Country code\',a)}</div>\n  <label>Real unit numbers (optional, one per line or comma-separated, e.g. Unit 1, Unit 2, Unit 3)</label><textarea id="baunits_list" rows="3" style="width:100%" placeholder="Leave blank to skip. Units are handed out to profiles in rotation as address line 2."></textarea><label class="cbl"><input type="checkbox" id="baunique"> Give each profile its own spelling of this address (rejig)</label><label class="cbl"><input type="checkbox" id="baunits" checked> Allow unit lines (Apt 3, #B…)</label>`,\n  async()=>{const addr=readForm(a);const ids=$(\'#bascope\').value==\'ticked\'?[...sel.prof]:null;if($(\'#bascope\').value==\'ticked\'&&!ids.length)return{error:\'Tick some profiles first\'};\n    if(!confirm(\'Update \'+(ids?ids.length:\'all\')+\' profiles for \'+$(\'#basite\').value+\'?\'))return{error:\'Cancelled\'};\n    const r=await api(\'vprofiles/bulk_address\',{site:$(\'#basite\').value,ids,address:addr,unique:$(\'#baunique\').checked,use_units:$(\'#baunits\').checked,target:$(\'#batarget\').value,units:$(\'#baunits_list\').value.split(/[\\n,]+/)});if(!r.error)toast(r.updated+\' profiles updated. \'+(r.note||\'\'));return r},\'wide\');\n}\nfunction ordDlg(){\n  dlg(inp(\'retailer\',\'Retailer\',\'Target\')+inp(\'order_number\',\'Order number\',\'\',\'text\',\'required\')+inp(\'date\',\'Date\',new Date().toISOString().slice(0,10),\'date\')+inp(\'total\',\'Total\',\'\',\'number\',\'step=0.01\')+\n   inp(\'item\',\'First item name\')+inp(\'qty\',\'Qty\',1,\'number\')+inp(\'price\',\'Unit price\',\'\',\'number\',\'step=0.01\'),\n   fd=>api(\'orders\',{retailer:fd.retailer,order_number:fd.order_number,date:fd.date,total:fd.total?+fd.total:null,items:fd.item?[{name:fd.item,qty:+fd.qty,price:+fd.price||0}]:[]}));\n}\nfunction itemsDlg(id){\n  const o=data.ord.find(x=>x.id==id);\n  const lines=o.items.map(i=>`${i.qty} | ${i.unit_price} | ${i.name}`).join(\'\\n\');\n  dlg(`<label>One item per line: qty | unit price | name</label><textarea name="t" rows="7" style="width:100%;font:inherit">${esc(lines)}</textarea>`,\n   fd=>api(\'orders/items\',{id,items:fd.t.split(\'\\n\').map(l=>l.split(\'|\').map(s=>s.trim())).filter(p=>p.length>=3&&p[2]).map(p=>({qty:+p[0]||1,price:+p[1]||0,name:p.slice(2).join(\'|\')}))}));\n}\nasync function setStatus(id,status){await api(\'orders/status\',{id,status});load()}\nasync function recv(id){await api(\'orders/receive\',{id});load()}\nasync function resolve(id){await api(\'review/resolve\',{id});load()}\nconst inp=(n,l,v=\'\',t=\'text\',x=\'\')=>`<label>${l}</label><input name="${n}" type="${t}" value="${esc(v)}" ${x}>`;\nfunction dlg(html,onok,wide){\n  $(\'#dlg\').classList.toggle(\'wide\',!!wide);\n  $(\'#form\').innerHTML=html+`<div style="margin-top:14px;display:flex;gap:8px;justify-content:flex-end"><button class="b" type="button" onclick="$(\'#dlg\').close()">Cancel</button><button class="b p" type="submit">Save</button></div>`;\n  $(\'#form\').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData($(\'#form\')));const btn=$(\'#form button[type=submit]\');btn.disabled=true;\n    try{const r=await onok(fd);if(r&&r.error){toast(r.error,true);return}$(\'#dlg\').close();load()}catch(err){toast(\'Something went wrong: \'+err.message,true)}finally{btn.disabled=false}};\n  $(\'#dlg\').showModal();\n}\nfunction updBadge(){\n  const b=$(\'#banner\'),s=UPD.status||{},i=UPD.info;\n  if(s.phase==\'ready\'){b.className=\'on\';b.innerHTML=\'<span>✅ An update has been downloaded and is ready.</span><button onclick="installUpdate()">Install &amp; restart</button>\'}\n  else if(s.phase==\'downloading\'){b.className=\'on\';b.innerHTML=\'<span>Downloading update…</span>\'}\n  else if(i&&i.ok&&i.update){b.className=\'on\';b.innerHTML=\'<span>⬆ A new version is available.</span><button onclick="startUpdate()">Download</button>\'}\n  else b.className=\'\';\n  nav();\n}\nasync function autoUpdate(){\n  const r=await checkUpdate(true);\n  if(r&&r.ok&&r.update&&(TS.settings||{}).auto_update&&UPD.status.phase!=\'downloading\'&&UPD.status.phase!=\'ready\'){await startUpdate()}\n}\n$(\'#rescanbtn\').onclick=async()=>{if(!confirm(\'Re-read every email in your look-back window? Safe: statuses only move forward and stock is never added twice.\'))return;const r=await api(\'sync\',{rescan:true});if(r.error&&r.error!=\'already running\')return toast(r.error,true);poll()};\n$(\'#syncbtn\').onclick=async()=>{const r=await api(\'sync\',{});if(r.error&&r.error!=\'already running\')return toast(r.error,true);poll()};\nlet timer,SYNCLOG=\'\';\nasync function poll(){\n  const s=await api(\'sync\');\n  $(\'#syncbtn\').disabled=s.running;$(\'#rescanbtn\').disabled=s.running;\n  const lines=(s.log||[]);$(\'#syncmsg\').textContent=s.running?\'Syncing… \'+(lines.length?lines[lines.length-1].slice(0,60):\'\'):(s.error?\'Sync failed — see Orders\':\'\');\n  SYNCLOG=lines.slice(-60).join(\'\\n\')+(s.error?\'\\nERROR: \'+s.error:\'\')+(s.stats?\'\\nDone: \'+JSON.stringify(s.stats):\'\');\n  const lg=document.getElementById(\'log\');if(lg)lg.textContent=SYNCLOG;\n  if(s.running)timer=setTimeout(poll,1000);else if(!poll.first||s.stats){poll.first=1;load()}\n}\napplyPriv();\nload().then(()=>{poll();setTimeout(autoUpdate,1500)});\n</script></body></html>\n'
